function worldObject(t){if(!t)return null;if(['capy','camp','decor','beach'].includes(t.kind))return lifeWorldObject(t);if(t.kind==='resource')return resources.includes(t.ref)&&t.ref.g.visible?t.ref.g:null;if(t.kind==='sapling')return s.saplings.includes(t.ref)?saplingObjects.get(t.ref):null;if(t.kind==='mushroom')return !t.ref.collected?mushroomObjects.get(t.ref):null;if(t.kind==='building')return buildingGroups.get(t.id);if(t.kind==='monster')return !t.ref.dead?t.ref.g:null;if(t.kind==='island')return t.ref.g;if(t.kind==='boat')return boat?.visible?boat:null;if(t.kind==='talk')return t.ref===visitorMesh||t.ref===board||npcs.includes(t.ref)||animals.includes(t.ref)?t.ref:null;return null;}
function worldName(t){if(t.kind==='capy')return '카피 · 카피바라';if(t.kind==='camp')return '우리의 모닥불';if(t.kind==='decor')return DECOR.find(d=>d.id===t.ref.kind).name;if(t.kind==='beach')return '해변의 선물';if(t.kind==='resource')return {wood:'나무',stone:'바위',food:'열매 덤불'}[t.ref.type];if(t.kind==='sapling')return '열매나무';if(t.kind==='mushroom')return '비 온 뒤 버섯';if(t.kind==='monster')return '바다 괴물';if(t.kind==='island')return s.discovered.includes(islands.indexOf(t.ref))?t.ref.name:'미지의 섬';if(t.kind==='boat')return '나의 배';if(t.kind==='building')return defs.find(d=>d.id===t.id)?.name||'주민 주택';return t.ref===board?'게시판':t.ref===visitorMesh?s.visitor?.name||'방문자':t.ref.userData.resident?.name||'숲속 친구';}
function worldActions(t){if(!worldObject(t))return [];const special=lifeActions(t);if(special)return special;if(t.kind==='resource')return [{key:'gather',label:{wood:'🪵 목재 모으기',stone:'🪨 돌 모으기',food:'🍎 열매 따기'}[t.ref.type],range:2.05,disabled:t.ref.cool>0,reason:'잠깐 기다리면 다시 모을 수 있어요.'}];if(t.kind==='mushroom')return [{key:'mushroom',label:'🍄 버섯 모으기',range:1.75}];if(t.kind==='sapling')return [{key:'fruit',label:'🍎 열매 따기',range:2,disabled:t.ref.age<30||s.time<(t.ref.fruitReadyAt||0),reason:t.ref.age<30?'나무가 자랄 때까지 기다려 주세요.':'열매가 다시 익는 중이에요.'},{key:'chop',label:'🪵 나무 베기',range:2}];if(t.kind==='talk')return [{key:'talk',label:t.ref===board?'📜 이벤트 보기':'💬 이야기하기',range:t.ref===board?2:1.65}];if(t.kind==='monster')return [{key:'attack',label:'⚔️ 공격하기',range:10.5}];if(t.kind==='island'){const i=islands.indexOf(t.ref);return s.discovered.includes(i)&&!s.colonies.includes(i)?[{key:'settle',label:'🏝️ 정착지 건설',range:t.ref.r+4.8,disabled:!afford({wood:25,stone:15,food:10}),reason:'목재 25 · 석재 15 · 식량 10이 필요해요.'},{key:'islandInfo',label:'ⓘ 섬 살펴보기',range:0}]:[{key:'explore',label:'🧭 섬 살펴보기',range:t.ref.r+4.8}];}if(t.kind==='boat')return [{key:'sail',label:'⛵ 출항하기',range:0},{key:'sailingInfo',label:'ⓘ 항해 안내',range:0}];
if(t.kind==='building'){const home=s.homes.find(h=>h.id===t.id),d=defs.find(d=>d.id===(home?'house':t.id)),lv=home?.level||level(s,t.id);const list=[{key:'details',label:'ⓘ 자세히 보기',range:0}];if(lv<3)list.push({key:'upgrade',label:'⬆️ 업그레이드',range:0,disabled:!upgradeAllowed(d,lv)||!afford(upgradeCost(s,d,lv)),reason:'업그레이드 재료가 부족해요.'});list.push({key:'move',label:'↔️ 위치 바꾸기',range:0});if(t.id==='dock'&&level(s,'boat'))list.unshift({key:'sail',label:'⛵ 출항하기',range:0});return list;}return [];}
function clickableTargets(){if(sea)return [...monsters.filter(m=>!m.dead).map(ref=>({kind:'monster',ref})),...islands.map(ref=>({kind:'island',ref}))];return [...lifeTargets(),...resources.filter(r=>r.g.visible).map(ref=>({kind:'resource',ref})),...s.saplings.map(ref=>({kind:'sapling',ref})),...s.mushrooms.filter(p=>!p.collected).map(ref=>({kind:'mushroom',ref})),...[visitorMesh,board,...npcs,...animals].filter(Boolean).map(ref=>({kind:'talk',ref})),...[...buildingGroups.keys()].map(id=>({kind:'building',id})),...(level(s,'boat')?[{kind:'boat'}]:[])];}
function pickWorldTarget(){const entries=clickableTargets().map(target=>({target,object:worldObject(target)})).filter(v=>v.object&&v.object.visible);const roots=entries.map(v=>v.object);for(const hit of clickRay.intersectObjects(roots,true)){let o=hit.object,visible=true,entry=null;while(o){if(!o.visible){visible=false;break;}entry??=entries.find(v=>v.object===o);o=o.parent;}if(visible&&entry)return entry.target;}return null;}
function activateTarget(target){if(workTask||fishState)return;const actions=worldActions(target);cancelMove();if(!actions.length)return;if(actions.length===1){chooseWorldAction(target,actions[0].key);return;}contextSelection={target};$('#contextActions').hidden=false;$('#contextName').textContent=worldName(target);$('#contextChoices').innerHTML=actions.map(a=>`<button data-world-action="${a.key}" ${a.disabled?'disabled':''}>${a.label}</button>`).join('');$('#contextChoices').querySelectorAll('[data-world-action]').forEach(b=>b.onclick=()=>chooseWorldAction(target,b.dataset.worldAction));positionActionMenu();}
function closeActionMenu(){contextSelection=null;$('#contextActions').hidden=true;}
function menuBounds(x,y,w,h,width=viewWidth,height=viewHeight){const margin=10;let left=x+14;if(left+w>width-margin)left=x-w-14;return {left:Math.max(margin,Math.min(left,width-w-margin)),top:Math.max(margin,Math.min(y-h/2,height-h-52))};}
function positionActionMenu(){if(!contextSelection)return;const o=worldObject(contextSelection.target);if(!o){closeActionMenu();return;}const box=new THREE.Box3().setFromObject(o),p=box.getCenter(new THREE.Vector3());p.y=box.max.y+.12;p.project(camera);if(p.z<-1||p.z>1){closeActionMenu();return;}const menu=$('#contextActions'),pos=menuBounds((p.x+1)*viewWidth/2,(-p.y+1)*viewHeight/2,menu.offsetWidth||172,menu.offsetHeight||190);menu.style.left=pos.left+'px';menu.style.top=pos.top+'px';}
function chooseWorldAction(target,key){const action=worldActions(target).find(a=>a.key===key);closeActionMenu();if(!action)return;if(action.disabled){toast(action.reason||'지금은 이 행동을 할 수 없어요.');return;}cancelMove();if(!action.range){performWorldAction(target,key);return;}pendingAction={target,key,range:action.range,age:0,routeAge:1};updatePendingAction(0);}
function approachPoint(position,range){const actor=sea?boat:player;const delta=actor.position.clone().sub(position);delta.y=0;if(delta.lengthSq()<.001)delta.set(1,0,0);return position.clone().add(delta.normalize().multiplyScalar(Math.max(.2,range-.45)));}
function updatePendingAction(dt){if(!pendingAction||dialogue||placement||$('#detailDialog').open)return;const p=pendingAction,position=worldPosition(p.target);if(!position){cancelMove();return;}p.age+=dt;p.routeAge+=dt;const actor=sea?boat:player;const distance=Math.hypot(actor.position.x-position.x,actor.position.z-position.z);if(distance<=p.range){const target=p.target,key=p.key;cancelMove();performWorldAction(target,key);return;}if(p.age>45){cancelMove();toast('가까운 쪽으로 이동한 뒤 다시 선택해 주세요.');return;}if(p.routeAge>.45||!moveTarget){p.routeAge=0;const dest=approachPoint(position,p.range);if(!setMoveTarget(dest,true)){cancelMove();toast('지금은 다가갈 수 없는 곳이에요.');}}}
function gatherResource(r){return collectResource(r);}
function gatherMushroom(p){return collectShroom(p);}
function gatherSapling(p,chop=false){return collectTree(p,chop);}
function performWorldAction(t,key){if(!worldObject(t))return false;if(performLifeAction(t,key))return true;if(key==='gather')return gatherResource(t.ref);if(key==='mushroom')return gatherMushroom(t.ref);if(key==='fruit'||key==='chop')return gatherSapling(t.ref,key==='chop');if(key==='talk'){talkTo(t.ref);return true;}if(key==='attack'){attack(t.ref);return true;}if(key==='sail'){sail();return true;}if(key==='sailingInfo'){showDetails('sailing');return true;}if(key==='settle'){colonize(islands.indexOf(t.ref));return true;}if(['islandInfo','explore'].includes(key)){showDetails('island',String(islands.indexOf(t.ref)));return true;}const h=s.homes.find(h=>h.id===t.id);if(key==='details'){showDetails(h?'home':'building',t.id);return true;}if(key==='upgrade')return upgrade(h?'house':t.id,h?.id);if(key==='move'){startPlacement(h?'house':t.id,'move',h?.id);return true;}return false;}
// Visibility graph around circular shores keeps touch sailing usable without a joystick.
function seaObstacles(){return [...regions.filter(regionOpen).map(a=>({x:a.x,z:a.z,r:a.r*1.1})),...islands.map(a=>({x:a.x,z:a.z,r:a.r+1}))];}
function seaPointValid(p){return Number.isFinite(p.x)&&Number.isFinite(p.z)&&Math.abs(p.x)<95&&Math.abs(p.z)<95&&seaObstacles().every(o=>Math.hypot(p.x-o.x,p.z-o.z)>o.r);}
function seaSegmentClear(a,b){const dx=b.x-a.x,dz=b.z-a.z,len=dx*dx+dz*dz;return seaObstacles().every(o=>{const t=len?THREE.MathUtils.clamp(((o.x-a.x)*dx+(o.z-a.z)*dz)/len,0,1):0;return Math.hypot(a.x+dx*t-o.x,a.z+dz*t-o.z)>o.r;});}
function seaPath(start,end){if(!seaPointValid(end))return null;if(seaSegmentClear(start,end))return [end.clone()];const points=[start.clone(),end.clone()];for(const o of seaObstacles())for(let i=0;i<16;i++){const p=new THREE.Vector3(o.x+Math.cos(i*Math.PI/8)*(o.r+1),0,o.z+Math.sin(i*Math.PI/8)*(o.r+1));if(seaPointValid(p))points.push(p);}const dist=Array(points.length).fill(Infinity),prev=Array(points.length).fill(-1),used=new Set();dist[0]=0;for(let k=0;k<points.length;k++){let u=-1;for(let i=0;i<points.length;i++)if(!used.has(i)&&(u<0||dist[i]<dist[u]))u=i;if(u<0||!Number.isFinite(dist[u]))break;if(u===1)break;used.add(u);for(let v=0;v<points.length;v++)if(!used.has(v)&&seaSegmentClear(points[u],points[v])){const next=dist[u]+points[u].distanceTo(points[v]);if(next<dist[v]){dist[v]=next;prev[v]=u;}}}if(!Number.isFinite(dist[1]))return null;const route=[];for(let u=1;u!==0;u=prev[u]){if(u<0)return null;route.unshift(points[u]);}return route;}
function updateActionUI(){positionActionMenu();const enemy=sea&&monsters.some(m=>!m.dead&&Math.hypot(m.g.position.x-boat.position.x,m.g.position.z-boat.position.z)<12);$('#seaFire').hidden=true;$('#keyboardControls').hidden=touchInput;$('#touchGuide').hidden=!touchInput;$('#keyboardCombat').hidden=true;$('#placementShortcuts').hidden=!placement;$('#touchGuide').textContent=sea?'왼쪽 드래그로 항해 · 섬을 터치해 탐험':'왼쪽 드래그로 이동 · 대상 터치로 행동';}
$('#contextClose').onclick=closeActionMenu;$('#seaFire').onclick=()=>{closeActionMenu();attack();};document.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')setInputMode(true);if(contextSelection&&!$('#contextActions').contains(e.target))closeActionMenu();});

const keys={};
// Use physical keys so Korean IME and other keyboard layouts still control movement.
function controlKey(e){return ({KeyW:'w',KeyA:'a',KeyS:'s',KeyD:'d',KeyE:'e',Space:' ',ArrowUp:'arrowup',ArrowDown:'arrowdown',ArrowLeft:'arrowleft',ArrowRight:'arrowright'})[e.code]||String(e.key||'').toLowerCase();}
function clearKeys(){Object.keys(keys).forEach(k=>keys[k]=false);}
addEventListener('keydown',e=>{if(e.code==='Escape'){closeActionMenu();cancelPlacement();if(dialogue)skipDialogue();return;}if(placement&&e.code==='KeyR'){rotatePlacement();return;}if(dialogue)return;if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.activeElement.isContentEditable||$('#welcome').open||$('#helpDialog').open||$('#detailDialog').open)return;const k=controlKey(e);if(!['w','a','s','d','e',' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))return;if(e.metaKey||e.ctrlKey||e.altKey)return;e.preventDefault();setInputMode(false);keys[k]=true;if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k))cancelMove();if(k==='e'&&!e.repeat)interact();});
addEventListener('keyup',e=>{keys[controlKey(e)]=false;});addEventListener('blur',()=>{clearKeys();cancelMove();});
