function stopJoystick(){joystick=null;$('#floatingJoystick').hidden=true;$('#joystickKnob').style.transform='translate(-50%,-50%)';}
function canStartJoystick(e){return touchPoint(e)&&!seaOrModalBlocked()&&e.clientX<viewWidth*.45&&e.clientY>viewHeight*.5;}
function seaOrModalBlocked(){return !!placement||!!dialogue||$('#welcome').open||$('#detailDialog').open||$('#helpDialog').open;}
function trackJoystick(e){if(!joystick||joystick.id!==e.pointerId)return false;const dx=e.clientX-joystick.x,dy=e.clientY-joystick.y,length=Math.hypot(dx,dy);if(!joystick.active){if(length<=7)return false;joystick.active=true;drag=true;cancelMove();clearKeys();$('#floatingJoystick').hidden=false;$('#floatingJoystick').style.left=joystick.x+'px';$('#floatingJoystick').style.top=joystick.y+'px';}const radius=43,scale=length>radius?radius/length:1;joystick.dx=dx*scale/radius;joystick.dz=dy*scale/radius;joystick.strength=Math.min(1,length/radius);$('#joystickKnob').style.transform=`translate(calc(-50% + ${dx*scale}px),calc(-50% + ${dy*scale}px))`;return true;}
const gesturePointers=new Map();let pinchState=null,gestureBlocked=false;
const MIN_ZOOM=4.5,MAX_ZOOM=80;
function setZoom(value){zoom=THREE.MathUtils.clamp(value,MIN_ZOOM,MAX_ZOOM);}
function resetGesture(){stopJoystick();gesturePointers.clear();pinchState=null;gestureBlocked=false;pointerOrigin=null;drag=false;}
function touchPoint(e){return e.pointerType==='touch';}
function beginPinch(){stopJoystick();const [a,b]=[...gesturePointers.values()];if(!a||!b)return;pinchState={distance:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y)),zoom};gestureBlocked=true;pointerOrigin=null;drag=false;cancelMove();clearKeys();}
function updatePlacementPointer(e){if(!placement)return;const rect={left:0,top:0,width:viewWidth,height:viewHeight};clickRay.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const pt=clickRay.ray.intersectPlane(clickPlane,new THREE.Vector3());if(pt){placement.x=pt.x;placement.z=pt.z;refreshGhost();}}
renderer.domElement.onpointerdown=e=>{e=gamePointer(e);if(e.button!==0)return;setInputMode(touchPoint(e));renderer.domElement.focus({preventScroll:true});renderer.domElement.setPointerCapture(e.pointerId);if(touchPoint(e)){gesturePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesturePointers.size>=2){if(!pinchState)beginPinch();return;}if(gestureBlocked)return;}pointerOrigin={x:e.clientX,y:e.clientY,id:e.pointerId};drag=false;lastX=e.clientX;lastY=e.clientY;if(canStartJoystick(e))joystick={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dz:0,strength:0,active:false};};
renderer.domElement.onpointermove=e=>{e=gamePointer(e);if(gesturePointers.has(e.pointerId))gesturePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesturePointers.size>=2){if(!pinchState)beginPinch();const [a,b]=[...gesturePointers.values()];const distance=Math.max(1,Math.hypot(a.x-b.x,a.y-b.y));setZoom(pinchState.zoom*pinchState.distance/distance);return;}if(gestureBlocked)return;if(joystick?.id===e.pointerId){trackJoystick(e);return;}updatePlacementPointer(e);if(!pointerOrigin||pointerOrigin.id!==e.pointerId)return;if(!drag&&Math.hypot(e.clientX-pointerOrigin.x,e.clientY-pointerOrigin.y)>6){drag=true;cancelMove();}if(drag){yaw-=(e.clientX-lastX)*.006*(s.sensitiveCamera?.5:1);pitch=THREE.MathUtils.clamp(pitch+(e.clientY-lastY)*.005*(s.sensitiveCamera?.5:1),.12,1.25);}lastX=e.clientX;lastY=e.clientY;};
function endPointer(e,cancelled=false){e=gamePointer(e);const wasJoystick=joystick?.id===e.pointerId&&joystick.active;if(joystick?.id===e.pointerId)stopJoystick();gesturePointers.delete(e.pointerId);if(wasJoystick){pointerOrigin=null;drag=false;return;}if(gestureBlocked){if(!gesturePointers.size)resetGesture();return;}if(pointerOrigin&&pointerOrigin.id===e.pointerId){if(!cancelled&&!drag&&Math.hypot(e.clientX-pointerOrigin.x,e.clientY-pointerOrigin.y)<=6)clickGround(e);pointerOrigin=null;drag=false;}if(cancelled&&!gesturePointers.size)resetGesture();}
renderer.domElement.onpointerup=e=>endPointer(e);renderer.domElement.onpointercancel=e=>endPointer(e,true);renderer.domElement.onlostpointercapture=e=>{if(gesturePointers.has(e.pointerId))endPointer(e,true);};
renderer.domElement.onwheel=e=>{e.preventDefault();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?viewHeight:1);setZoom(zoom*Math.exp(delta*.0015));};addEventListener('blur',resetGesture);

