addEventListener('resize',()=>{camera.aspect=viewWidth/viewHeight;camera.updateProjectionMatrix();renderer.setSize(viewWidth,viewHeight);});document.addEventListener('visibilitychange',()=>{clock.getDelta();if(document.hidden){clearKeys();cancelMove();save();}if(audioReady&&musicMaster)musicMaster.gain.setTargetAtTime(document.hidden?0:(s.audioOn?s.volume:0),audio.currentTime,.5);});addEventListener('pagehide',save);
function update(dt){updateWorld(dt);updateReward(dt);updateEffects(dt);updateLife(dt);islands.forEach(a=>a.g.visible=sea);monsters.forEach(m=>m.g.visible=sea&&!m.dead);elapsed+=dt;attackCD=Math.max(0,attackCD-dt);harvestCD=Math.max(0,harvestCD-dt);for(const r of resources)r.cool=Math.max(0,r.cool-dt);const target=sea?boat:player;const previousPosition=player.position.clone();let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);let remaining=Infinity;if(joystick?.active){dx=joystick.dx;dz=joystick.dz;}
if(dialogue||placement||$('#detailDialog').open){dx=0;dz=0;}else if(dx||dz)cancelMove();else if(moveTarget){const tx=moveTarget.x-target.position.x,tz=moveTarget.z-target.position.z;remaining=Math.hypot(tx,tz);if(remaining<.04){if(moveRoute.length)moveTarget=moveRoute.shift();else{moveTarget=null;destinationMarker.visible=false;}}else{dx=Math.cos(yaw)*tx-Math.sin(yaw)*tz;dz=Math.sin(yaw)*tx+Math.cos(yaw)*tz;}}
if(moveTarget){const pulse=1+Math.sin(elapsed*5)*.12;destinationMarker.scale.setScalar(pulse);}
if(dx||dz){focusPoint=null;standUp();const l=Math.hypot(dx,dz);dx/=l;dz/=l;const speed=sea?(s.buildings.ship?6.2:4.7):4.2;const step=Math.min(speed*dt*(joystick?.active?joystick.strength:1),remaining);const mx=(Math.cos(yaw)*dx+Math.sin(yaw)*dz)*step,mz=(-Math.sin(yaw)*dx+Math.cos(yaw)*dz)*step;const next=target.position.clone().add(new THREE.Vector3(mx,0,mz));if(sea){if(!insideLand(next.x,next.z, -1.5)&&!islands.some(a=>Math.hypot(next.x-a.x,next.z-a.z)<a.r+.9)){target.position.copy(next);}target.position.x=THREE.MathUtils.clamp(target.position.x,-95,95);target.position.z=THREE.MathUtils.clamp(target.position.z,-95,95);}else if(walkable(next.x,next.z))target.position.copy(next);target.rotation.y=Math.atan2(mx,mz);}
player.position.y=.45;animateHuman(player,dt,sea?0:Math.hypot(player.position.x-previousPosition.x,player.position.z-previousPosition.z));playerMarker.position.set(player.position.x,.44,player.position.z);if(sea)boat.position.y=Math.sin(elapsed*2)*.08;const center=focusPoint?focusPoint.clone():sea?boat.position.clone():player.position.clone();center.y=sea?.6:THREE.MathUtils.lerp(1.35,0,THREE.MathUtils.clamp((zoom-5)/20,0,1));const offset=new THREE.Vector3(Math.sin(yaw)*zoom*Math.cos(pitch),zoom*Math.sin(pitch),Math.cos(yaw)*zoom*Math.cos(pitch));camera.position.lerp(center.clone().add(offset),Math.min(1,dt*4));camera.lookAt(center.x,center.y,center.z);
nearest=null;if(!sea){let min=2.1;for(const r of resources){if(!r.g.visible)continue;const d=Math.hypot(r.x-player.position.x,r.z-player.position.z);if(d<min){min=d;nearest=r;}}}npcs.forEach((n,i)=>{const r=s.residents[i],social=residentDestination(r,i),origin=placementOf(({wood:'lumber',stone:'quarry',food:'farm'})[r.jobKey]||'haven');const wanted={x:(social?.x??origin.x)+Math.sin(i*2)*3,z:(social?.z??origin.z)+3};let motion=n.userData.motion;if(!motion){n.position.copy(visitorPosition);motion=n.userData.motion={route:[],timer:0};}motion.timer-=dt;if(motion.timer<=0){motion.timer=5+Math.random()*3;motion.route=landPath(n.position,wanted)||[];}const previous=n.position.clone(),goal=motion.route[0];if(goal){const delta=goal.clone().sub(n.position);delta.y=0;const d=delta.length();if(d<.15)motion.route.shift();else{const step=Math.min(d,dt*.75);const next=n.position.clone().addScaledVector(delta.normalize(),step);if(walkable(next.x,next.z)){n.position.copy(next);n.rotation.y=Math.atan2(delta.x,delta.z);}else motion.timer=0;}}n.position.y=.45;animateHuman(n,dt,previous.distanceTo(n.position));n.userData.umbrella.visible=s.weather==='rain';});animals.forEach((a,i)=>wanderAnimal(a,i,dt));waves.forEach((w,i)=>{w.position.y=-.58+Math.sin(elapsed+i)*.025;});
if(sea){islands.forEach((a,i)=>{if(!s.discovered.includes(i)&&Math.hypot(boat.position.x-a.x,boat.position.z-a.z)<a.r+7){s.discovered.push(i);gainItems({crystal:2,gold:15});toast(`${a.name} 발견! 가까이 접근해 항해 탭에서 정착하세요.`);beep(880);render();save();}});}

for(let i=shots.length-1;i>=0;i--){const q=shots[i];q.life-=dt;q.g.position.lerp(q.target,dt*15);if(q.life<=0){scene.remove(q.g);shots.splice(i,1);}}
workTick+=dt;saveTick+=dt;if(workTick>=4){workTick=0;produce();render();}if(saveTick>=8){saveTick=0;save();}updatePendingAction(dt);updateActionUI();}
// --- Construction, island life and atmosphere ---
const buildingGroups=new Map();let nightWindows=[],aquatic=[],visitorMesh=null,placement=null,ghost=null,dialogue=null,dialogueCooldown=0;
const natureGroup=new THREE.Group();scene.add(natureGroup);
const board=new THREE.Group();board.position.set(3,.4,5);scene.add(board);box(1.7,1.1,.16,mats.wood,0,1.4,0,board);for(const x of [-.65,.65])box(.14,1.8,.14,mats.trunk,x,.9,0,board);box(1.3,.75,.05,mats.white,0,1.4,.12,board);
function disposeBranch(root){const cached=new Set(shapeCache.values()),shared=new Set(Object.values(mats)),geos=new Set(),materials=new Set();root.traverse(o=>{if(o.isMesh){if(o.geometry&&!cached.has(o.geometry))geos.add(o.geometry);const list=Array.isArray(o.material)?o.material:[o.material];for(const m of list)if(m&&!shared.has(m))materials.add(m);}});for(const g of geos)g.dispose();for(const m of materials)m.dispose();}
function placementOf(id){const d=defs.find(v=>v.id===id);return s.placements[id]||{x:d?.origin[0]||0,z:d?.origin[1]||0,rotation:0};}
function harborSpawn(){const p=placementOf('dock'),len=Math.hypot(p.x,p.z)||24;let r=28;while(r<85&&regions.filter(regionOpen).some(a=>Math.hypot(p.x/len*r-a.x,p.z/len*r-a.z)<a.r*1.1+1))r++;return new THREE.Vector3(p.x/len*r,0,p.z/len*r);}
function attachUmbrella(n){const g=new THREE.Group();cyl(0,.8,.35,'#a4b4c9',0,2.55,0,g,16);cyl(.025,.025,1.1,mats.trunk,.25,2,0,g);n.add(g);g.visible=false;n.userData.umbrella=g;}
function dressBuilding(g,id,lv){
const d=defs.find(v=>v.id===id);g.scale.set(1+(lv-1)*.025,1+(lv-1)*.12,1+(lv-1)*.025);
g.traverse(o=>{if(o.isMesh&&o.material===mats.blue){o.material=o.material.clone();o.material.emissive=new THREE.Color('#ffd38a');nightWindows.push(o.material);}if(o.isMesh&&lv===3&&o.material===mats.wall)o.material=mat('#cfb8a3');});
if(lv>=2){for(const x of [-d.radius*.65,d.radius*.65]){box(.12,1.3,.12,mats.trunk,x,1,1.7,g);const bulb=orb(.17,.23,.17,'#ffd88e',x,1.7,1.7,g);bulb.material.emissive=new THREE.Color('#ffcb75');nightWindows.push(bulb.material);if(['house','store','plaza','council'].includes(id)&&nightWindows.filter(m=>m.isLight).length<8){const light=new THREE.PointLight('#ffd292',0,5,2);light.position.set(x,1.9,1.7);g.add(light);nightWindows.push(light);}}if(d.category==='nature'||id==='farm')for(let i=0;i<6;i++)orb(.16,.2,.16,i%2?'#e7b0a0':'#f3db91',Math.sin(i)*d.radius,.6,Math.cos(i)*d.radius,g);}
if(lv===3){if(d.category==='nature'||id==='farm'){for(let i=0;i<8;i++){box(.12,.55,.12,mats.wood,Math.sin(i*.8)*d.radius,.7,Math.cos(i*.8)*d.radius,g);}}else{box(.5,.9,.5,mats.rock,1.1,3.4,-.6,g);box(1,.2,1,mats.roof,1.1,3.9,-.6,g);}}
}
function drawPlaced(id,fn){const before=new Set(structure.children);fn();const d=defs.find(v=>v.id===id),p=placementOf(id),g=new THREE.Group();for(const o of [...structure.children])if(!before.has(o)&&!animals.includes(o)){o.position.x-=d.origin[0];o.position.z-=d.origin[1];g.add(o);}g.position.set(p.x,0,p.z);g.rotation.y=p.rotation||0;structure.add(g);dressBuilding(g,id,level(s,id));buildingGroups.set(id,g);}
function drawExtraHome(h){const before=new Set(structure.children);cottage(0,0);const g=new THREE.Group();for(const o of [...structure.children])if(!before.has(o))g.add(o);g.position.set(h.x,0,h.z);g.rotation.y=h.rotation;structure.add(g);dressBuilding(g,'house',h.level);buildingGroups.set(h.id,g);}
function footprintEntries(){return defs.filter(d=>level(s,d.id)&&!['boat','ship'].includes(d.id)).map(d=>({id:d.id,...placementOf(d.id),radius:d.radius*1.05})).concat(s.homes.map(h=>({...h,radius:2.3})),s.decorPlaced.filter(d=>!['path','flowers'].includes(d.kind)).map(d=>({...d,radius:DECOR.find(k=>k.id===d.kind).radius})));}
function validPlacement(id,x,z,skip=null){if(!Number.isFinite(x)||!Number.isFinite(z))return false;const d=defs.find(v=>v.id===id)||(id.startsWith('decor:')?DECOR.find(d=>d.id===id.slice(6)):null),r=d?.radius||1.1;const dist=Math.hypot(x,z);if(id==='dock'){if(dist<22||dist>24.2)return false;}else if(id==='fishing'){if(dist<20||dist>22)return false;}else if(!insideLand(x,z,r*1.05))return false;
if(id!=='sapling'&&footprintEntries().some(p=>p.id!==skip&&Math.hypot(x-p.x,z-(p.z+p.radius+1.2))<r+.8))return false;
if(capybara&&Math.hypot(x-capybara.position.x,z-capybara.position.z)<r+1)return false;
if(Math.hypot(x-board.position.x,z-board.position.z)<r+1.3)return false;return !footprintEntries().some(p=>p.id!==skip&&Math.hypot(x-p.x,z-p.z)<r+p.radius+.35)&&!s.saplings.some(p=>Math.hypot(x-p.x,z-p.z)<r+1.1);}
function syncResources(){for(const r of resources)r.g.visible=insideLand(r.x,r.z)&&!footprintEntries().some(p=>Math.hypot(r.x-p.x,r.z-p.z)<p.radius+.5);}
function buildingPreview(id){const builders={'house':()=>{box(2.4,1.8,2.1,mats.wall,1,1.3,-1,structure);const roof=box(2.9,.45,2.7,mats.roof,1,2.45,-1,structure);box(2,.35,2.2,mats.roof,1,2.8,-1,structure);box(.6,1.1,.08,mats.trunk,1,.96,.09,structure);box(.55,.55,.08,mats.blue,.25,1.6,.1,structure);box(.55,.55,.08,mats.blue,1.75,1.6,.1,structure);},'store':()=>{box(2,1.4,1.8,mats.wall,4,1.1,-.2,structure);box(2.5,.25,2.4,'#729b7a',4,2,-.2,structure);box(2.4,.15,.8,mats.wood,4,1,1,structure);for(let i=0;i<3;i++)box(.22,.22,.22,'#e2a45a',3.5+i*.45,1.2,1,structure);},'orchard':()=>{for(const x of [-11,-8,-5]){tree(x,-10,structure,false);for(let j=0;j<3;j++)orb(.19,.19,.19,'#eba960',x+Math.sin(j*2)*.7,2.7,-10+Math.cos(j*2)*.6,structure);}for(let i=0;i<3;i++){const a=new THREE.Group();orb(.25,.3,.38,'#eabf73',0,.4,0,a);orb(.2,.2,.2,'#f1d89c',0,.65,.2,a);box(.1,.08,.15,'#bb8254',0,.63,.4,a);orb(.24,.08,.18,'#c39055',-.27,.4,0,a);orb(.24,.08,.18,'#c39055',.27,.4,0,a);a.userData.kind='bird';structure.add(a);animals.push(a);}},'pond':()=>{const water=cyl(3,3,.06,'#82c8ca',-11,.46,3,structure,48);for(let i=0;i<12;i++)orb(.35,.22,.35,mats.rock,-11+Math.sin(i*.53)*3,.5,3+Math.cos(i*.53)*3,structure);for(let i=0;i<3;i++){const a=new THREE.Group();orb(.45,.48,.8,'#bc966e',0,.85,0,a);orb(.3,.4,.3,'#cba87d',0,1.35,.65,a);for(const x of [-.25,.25])for(const z of [-.4,.4])cyl(.07,.08,.7,mats.trunk,x,.4,z,a);orb(.12,.25,.08,'#bc966e',-.22,1.7,.65,a);orb(.12,.25,.08,'#bc966e',.22,1.7,.65,a);orb(.07,.07,.08,'#3d4a40',0,1.3,.94,a);a.userData.kind='deer';structure.add(a);animals.push(a);}},'farm':()=>{box(5,.12,4,'#967654',10,.48,8,structure);for(let i=0;i<4;i++)for(let j=0;j<4;j++){orb(.18,.18,.18,'#dd9c51',8.3+i*1.1,.65,6.6+j*.9,structure);orb(.07,.25,.07,mats.leaf2,8.3+i*1.1,.9,6.6+j*.9,structure);}},'lumber':()=>{box(4,.2,3,mats.wood,-11,.55,-4,structure);for(let i=0;i<6;i++){const log=cyl(.25,.25,2.6,mats.trunk,-12+i*.42,.9,-4,structure);log.rotation.z=Math.PI/2;}box(4.5,.3,3.5,'#82976b',-11,2.8,-4,structure);for(const x of [-13,-9])box(.2,2.2,.2,mats.wood,x,1.6,-4,structure);},'quarry':()=>{box(4,.2,3,'#afb5a6',12,.55,-7,structure);for(let i=0;i<5;i++)box(.8,.65,.7,mats.rock,11+i*.4,.9+i%2*.5,-7,structure);cottage(12,-11,mats.blue);},'cottages':()=>{cottage(-2.5,11,'#7fa4a0');cottage(2.5,11,'#caa26a');},'warehouse':()=>{cottage(12,0,'#8c9ba9');for(let i=0;i<4;i++)box(.8,.8,.8,mats.wood,10.6+i*.85,.9,2.4,structure);},'plaza':()=>{cyl(4.2,4.2,.12,'#d6cfb3',0,.48,5,structure,48);cyl(1.2,1.3,.35,mats.rock,0,.75,5,structure,32);cyl(1,1,.05,'#8dc9ce',0,.95,5,structure,32);cyl(.2,.3,.8,mats.rock,0,1.2,5,structure);for(const x of [-3,3]){box(1.7,.2,.6,mats.wood,x,.9,5,structure);box(1.7,.7,.12,mats.wood,x,1.25,5.3,structure);}},'council':()=>{cottage(1,-12,'#718c93');box(4.5,.35,3.8,'#718c93',1,3.4,-12,structure);for(let i=0;i<3;i++)cyl(.14,.14,2,mats.white,-.3+i*1.3,1.5,-10.2,structure);},'dock':()=>{box(level(s,'dock')>=2?4:2.5,.3,5,mats.wood,0,.15,24.5,structure);for(let j=0;j<8;j++)box(level(s,'dock')>=2?4:2.5,.04,.04,'#795e43',0,.32,22.4+j*.6,structure);for(const x of [-1.1,1.1])for(const z of [22.5,26.5])box(.23,1.2,.23,mats.trunk,x,.3,z,structure);if(level(s,'dock')>=2){box(.3,3,.3,mats.wood,2,1.4,24,structure);box(3,.25,.25,mats.wood,1,2.8,24,structure);}}};if(!builders[id])return null;const before=new Set(structure.children),priorAnimals=new Set(animals);builders[id]();const group=new THREE.Group(),d=defs.find(d=>d.id===id);for(const o of [...structure.children])if(!before.has(o)){o.position.x-=d.origin[0];o.position.z-=d.origin[1];group.add(o);}animals=animals.filter(a=>priorAnimals.has(a));return group;}
function startPlacement(id,mode='build',homeId=null){standUp();if(sea){toast('귀항한 뒤 건설할 수 있어요.');return;}const d=defs.find(v=>v.id===id)||(id.startsWith('decor:')?{...DECOR.find(d=>d.id===id.slice(6)),id}:null);if(mode==='decor'&&(!havenLevel(s)||!d||(!(s.decorTokens?.[d.id.slice(6)]>0)&&!afford(d.cost))))return;if(mode==='build'&&(!d||level(s,id)||requirements(s,d).length||!afford(d.cost)))return;if(mode==='extra'&&!afford(extraHomeCost()))return;if(mode==='plant'&&!afford({wood:4,food:2}))return;cancelMove();cancelPlacement();const existing=mode==='decorMove'?s.decorPlaced.find(h=>h.id===homeId):homeId?s.homes.find(h=>h.id===homeId):null;const p=existing||((mode==='decor')?{x:player.position.x+2,z:player.position.z,rotation:0}:placementOf(id));placement={id,mode,homeId,x:mode==='plant'?player.position.x+2:p.x,z:mode==='plant'?player.position.z:p.z,rotation:p.rotation||0};ghost=new THREE.Group();const radius=id==='sapling'?1.1:d.radius;const material=new THREE.MeshBasicMaterial({color:'#8cb591',transparent:true,opacity:.35,depthWrite:false});const base=new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,.12,48),material);base.position.y=.5;ghost.add(base);const original=mode==='decorMove'?lifeDecorObjects.get(homeId):buildingGroups.get(homeId||id)||buildingPreview(id);if(original){const preview=original.clone(true);preview.position.set(0,0,0);preview.rotation.set(0,0,0);preview.traverse(o=>{if(o.isMesh){o.material=material;o.castShadow=false;}});ghost.add(preview);}else{const preview=new THREE.Group();if(id==='haven'){for(let i=0;i<3;i++){const log=box(1.3,.2,.2,material,0,.6,0,preview);log.rotation.y=i*Math.PI/3;}orb(.25,.5,.25,material,0,1,0,preview);}else if(id==='sapling'){cyl(.1,.18,1.6,material,0,1,0,preview);orb(.8,.8,.8,material,0,2,0,preview);}else{box(Math.min(radius*1.45,4),1.8,Math.min(radius*1.3,3.5),material,0,1.3,0,preview);const roof=box(Math.min(radius*1.7,4.5),.4,Math.min(radius*1.6,4),material,0,2.4,0,preview);box(.6,1,.1,material,0,1,radius*.65,preview);}ghost.add(preview);}const arrow=box(.24,.15,1.1,'#fff2b9',0,2.4,radius*.7,ghost);scene.add(ghost);$('#placementBar').hidden=false;panelOpen=false;render();refreshGhost();}
function refreshGhost(){if(!placement||!ghost)return;const p=placement;ghost.position.set(p.x,0,p.z);ghost.rotation.y=p.rotation;const ok=validPlacement(p.id,p.x,p.z,p.homeId|| (p.mode==='move'?p.id:null));ghost.children[0].material.color.set(ok?'#6cbe98':'#da8670');$('#placeStatus').textContent=`${p.mode==='move'?'이동':'배치'} · ${p.id==='sapling'?'열매나무':(defs.find(d=>d.id===p.id)||DECOR.find(d=>'decor:'+d.id===p.id))?.name||'장식'} · ${ok?'여기에 놓을 수 있어요':'건물·게시판과 겹치거나 섬 밖이에요'} · ${Math.round(p.rotation*180/Math.PI)%360}°`;}
function rotatePlacement(){if(placement){placement.rotation+=Math.PI/2;refreshGhost();}}
function cancelPlacement(){if(ghost){scene.remove(ghost);ghost.traverse(o=>{if(o.isMesh&&o.geometry.type==='CylinderGeometry')o.geometry.dispose();});}ghost=null;placement=null;$('#placementBar').hidden=true;}
function extraHomeCost(){return {wood:35+s.homes.length*5,stone:20,food:12};}
function commitPlacement(){if(!placement)return false;const p={...placement};if(!validPlacement(p.id,p.x,p.z,p.homeId||(p.mode==='move'?p.id:null)))return false;
if(p.mode==='decor'||p.mode==='decorMove'){const kind=p.id.slice(6),d=DECOR.find(d=>d.id===kind);if(p.mode==='decorMove'){const item=s.decorPlaced.find(d=>d.id===p.homeId);if(!item)return false;Object.assign(item,{x:p.x,z:p.z,rotation:p.rotation});}else{const free=(s.decorTokens?.[kind]||0)>0;if(!free&&!pay(d.cost))return false;if(free)s.decorTokens[kind]--;s.decorPlaced.push({id:'decor-'+Date.now()+'-'+s.decorPlaced.length,kind,x:p.x,z:p.z,rotation:p.rotation});}cancelPlacement();rebuildLifeWorld();render();save();toast(d.name+'를 놓았어요!');return true;}
if(p.mode==='plant'){const cost={wood:4,food:2};if(!afford(cost))return false;pay(cost);s.saplings.push({x:p.x,z:p.z,age:0});cancelPlacement();rebuildNature();const planted=s.saplings[s.saplings.length-1];reactObject(saplingObjects.get(planted),'build');burst(new THREE.Vector3(p.x,1,p.z),'food',10);startAction('pick');render();save();return true;}
if(p.mode==='extra'){const cost=extraHomeCost();if(!afford(cost))return false;pay(cost);s.homes.push({id:'home-'+Date.now()+'-'+s.homes.length,level:1,x:p.x,z:p.z,rotation:p.rotation});cancelPlacement();rebuild();constructionEffect('house',s.homes[s.homes.length-1].id);maybeVisitor(45);render();save();toast('새 주택 완성! 빈방을 보고 방문자가 찾아올 거예요.');return true;}
if(p.mode==='move'){if(p.homeId)Object.assign(s.homes.find(h=>h.id===p.homeId),{x:p.x,z:p.z,rotation:p.rotation});else s.placements[p.id]={x:p.x,z:p.z,rotation:p.rotation};cancelPlacement();rebuild();render();save();return true;}
const d=defs.find(v=>v.id===p.id);if(level(s,p.id)||requirements(s,d).length||!afford(d.cost))return false;pay(d.cost);s.buildings[p.id]=1;s.placements[p.id]={x:p.x,z:p.z,rotation:p.rotation};cancelPlacement();rebuild();afterConstruction(p.id);render();save();return true;}
function build(id){if(['boat','ship'].includes(id)){const d=defs.find(d=>d.id===id);if(sea||level(s,id)||requirements(s,d).length||!afford(d.cost))return false;pay(d.cost);s.buildings[id]=1;rebuild();constructionEffect(id);render();save();toast(d.name+' 제작 완료!');return true;}startPlacement(id);}
function upgrade(id,homeId=null){const d=defs.find(v=>v.id===id),h=homeId?s.homes.find(h=>h.id===homeId):null,lv=h?h.level:level(s,id);if(!d||lv<1||lv>=d.forms.length||sea)return false;if(!upgradeAllowed(d,lv)){toast('중심 보금자리를 먼저 발전시켜 주세요.');return false;}const cost=upgradeCost(s,d,lv);if(!afford(cost))return false;pay(cost);if(h)h.level++;else s.buildings[id]++;rebuild();updateRegions();constructionEffect(id,homeId);render();save();beep(720);toast(id==='haven'?HAVENS[lv].name+' 완성! '+(regions.find(a=>a.level===lv+1)?.name?'새 지역 '+regions.find(a=>a.level===lv+1).name+' · ':'')+HAVENS[lv].unlock+' 해금':d.name+' '+(lv+1)+'단계 완성!');if(id==='house'||id==='cottages')maybeVisitor(45);if(id==='council'&&level(s,id)===2)milestone('sailing','마을 대표',['마을의 기틀이 잡혔어요. 보금자리가 큰집으로 자라면 항구를 준비해요.','항구와 탐험선을 준비하면 바다 너머의 섬을 찾아갈 수 있어요.']);return true;}
function afterConstruction(id){constructionEffect(id);beep(660);toast(`${id==='haven'?HAVENS[havenLevel(s)-1].name:defs.find(d=>d.id===id).name} 완성!`);if(['house','cottages'].includes(id))maybeVisitor(45);const messages={habitat:['작은 토끼',['토끼가 조심스레 다가와 먹이터를 둘러봐요.','과일나무와 물 마실 곳을 마련하면 더 많은 친구가 찾아올 거예요.']],orchard:['숲의 새',['새가 과일나무 가지에 자리를 잡았어요.','열매나무를 더 심고 기다리면 새 둥지가 생겨요.']],pond:['숲속 관찰 기록',['연못에 물고기와 개구리가 나타났어요. 사슴도 물을 마시러 찾아오네요.']],house:['섬의 기록',['첫 빈방이 준비됐어요. 곧 이 섬에서 살고 싶은 사람이 찾아올 거예요.','방문자의 이야기를 듣고 입주를 허락해 주세요.']]};if(messages[id])milestone('built-'+id,...messages[id]);}
function rebuildNature(){saplingObjects.clear();mushroomObjects.clear();disposeBranch(natureGroup);natureGroup.clear();aquatic=[];for(const a of animals.filter(a=>a.userData.extra)){if(a.userData.standalone)disposeBranch(a);a.removeFromParent();}animals=animals.filter(a=>!a.userData.extra);for(const id of ['habitat','orchard','pond']){const kind=id==='habitat'?undefined:id==='orchard'?'bird':'deer',base=animals.find(a=>a.userData.kind===kind);if(base)for(let i=0;i<(level(s,id)-1)*2;i++){const a=base.clone(true);a.userData.kind=kind;a.userData.extra=true;structure.add(a);animals.push(a);}}
for(const p of s.saplings){const g=tree(p.x,p.z,natureGroup,false);saplingObjects.set(p,g);g.scale.setScalar(Math.min(1,.45+p.age/90));if(p.age>=30){orb(.3,.12,.3,mats.trunk,p.x,2.9,p.z,natureGroup);if(s.saplings.filter(q=>q.age>=30).indexOf(p)<6){const bird=new THREE.Group();orb(.22,.25,.32,'#e4ba73',0,.4,0,bird);orb(.17,.18,.17,'#efd6a0',0,.6,.2,bird);bird.userData={kind:'bird',extra:true,standalone:true,origin:[p.x,p.z]};structure.add(bird);animals.push(bird);}}}
if(level(s,'orchard')){const p=placementOf('orchard');for(let i=0;i<3;i++){const nest=cyl(.27,.3,.16,mats.trunk,p.x-2+i*2,2.9,p.z,natureGroup,16);orb(.09,.12,.09,mats.white,p.x-2+i*2,3.05,p.z,natureGroup);}}
if(level(s,'pond')){const p=placementOf('pond');for(let i=0;i<4;i++){const g=new THREE.Group();const fish=i<2;orb(fish?.32:.2,fish?.1:.16,fish?.12:.2,fish?'#e7aa72':'#87a66a',0,0,0,g);if(!fish){orb(.06,.07,.06,mats.white,-.11,.14,.1,g);orb(.06,.07,.06,mats.white,.11,.14,.1,g);}g.position.set(p.x+Math.sin(i)*1.8,.56,p.z+Math.cos(i)*1.8);natureGroup.add(g);aquatic.push({g,x:p.x,z:p.z,fish});}}
for(const [i,p]of s.mushrooms.entries()){if(p.collected)continue;const g=new THREE.Group();g.position.set(p.x,.45,p.z);cyl(.06,.1,.35,mats.white,0,.18,0,g,10);orb(.3,.14,.3,'#d4a5a1',0,.4,0,g);natureGroup.add(g);mushroomObjects.set(p,g);p.meshIndex=i;}
for(const [i,name]of s.decorations.entries()){const g=new THREE.Group();g.position.set(4+i*1.4,.5,7);cyl(.35,.25,.5,'#b98964',0,.2,0,g);for(let j=0;j<5;j++)orb(.15,.15,.15,'#e7b4ac',Math.sin(j)*.25,.8,Math.cos(j)*.25,g);natureGroup.add(g);}
}
const visitorPosition=new THREE.Vector3(2,.45,17);
function syncVisitor(){if(visitorMesh){disposeBranch(visitorMesh);scene.remove(visitorMesh);}visitorMesh=null;if(s.visitor){visitorMesh=human('#b79db4');visitorMesh.position.copy(visitorPosition);attachUmbrella(visitorMesh);scene.add(visitorMesh);}}
function maybeVisitor(dt){if(s.residents.length>=capacity(s)||s.visitor||sea)return; s.visitTimer+=dt;if(s.visitTimer<45)return;const available=PROFILES.filter(p=>level(s,p.need));if(!available.length)return;s.visitTimer=0;const p=available[s.visitorSerial%available.length];s.visitorSerial++;s.visitor={...p,name:p.name+(s.visitorSerial>4?' '+Math.ceil(s.visitorSerial/4):''),id:s.visitorSerial};syncVisitor();toast(`${s.visitor.name} 님이 섬을 찾아왔어요. 주민 메뉴에서 이야기를 들어보세요.`);render();save();}
function acceptVisitor(){if(!s.visitor||crew()>=capacity(s))return false;s.residents.push({...s.visitor,jobKey:null});const name=s.visitor.name;s.visitor=null;s.visitTimer=0;syncVisitor();rebuild();render();save();toast(`${name} 님이 새로운 이웃이 되었어요!`);return true;}
function declineVisitor(){s.visitor=null;s.visitTimer=0;syncVisitor();render();save();toast('다음 만남을 기약했어요. 새로운 방문자는 잠시 뒤 찾아와요.');}
function assignResident(id,job){const r=s.residents.find(r=>r.id===id);if(!r||!['wood','stone','food',null].includes(job))return;if(job&&s.residents.filter(v=>v.id!==id&&v.jobKey===job).length>=jobSlots(s,job)){toast('작업 자리가 가득 찼어요. 시설을 업그레이드해 주세요.');return;}r.jobKey=job;s.productionProgress[r.id]=0;syncJobs();render();save();}
function syncJobs(){s.jobs={wood:0,stone:0,food:0};s.residents.forEach(r=>{if(r.jobKey)s.jobs[r.jobKey]++;});}
function showDialogue(who,lines,choices=[]){if(dialogue)return;lines=lines.map(line=>line.replaceAll('준이',playerName()));document.body.classList.toggle('event-message',/기록|대표|작은 토끼|숲의 새|저녁 모임|모닥불/.test(who));cancelMove();clearKeys();resetGesture();startAction('wave');dialogue={who,lines,index:0,revealed:0,choices};panelOpen=false;render();$('#conversation').hidden=false;paintDialogue();}
function paintDialogue(){if(!dialogue)return;const d=dialogue,text=d.lines[d.index]||'';$('#speaker').textContent=d.who;$('#dialogueAvatar').textContent=/카피/.test(d.who)?'🦫':/토끼/.test(d.who)?'🐰':/새/.test(d.who)?'🐦':/숲/.test(d.who)?'🐾':/기록/.test(d.who)?'📖':/대표/.test(d.who)?'🧑‍🌾':'🙂';$('#dialogueText').textContent=text.slice(0,Math.floor(d.revealed));$('#dialogueCount').textContent=`${d.index+1} / ${d.lines.length}`;const end=d.index===d.lines.length-1&&d.revealed>=text.length;$('#dialogueChoices').innerHTML=end?d.choices.map((c,i)=>`<button data-choice="${i}" class="${i===0?'primary':''}">${c.label}</button>`).join(''):'';$('#dialogueNext').hidden=end&&d.choices.length>0;$('#dialogueNext').textContent=d.revealed<text.length?'바로 읽기':d.index<d.lines.length-1?'다음 →':'대화 마치기';$('#dialogueChoices').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>chooseDialogue(+b.dataset.choice));}
function advanceDialogue(){if(!dialogue)return;const d=dialogue,text=d.lines[d.index];if(d.revealed<text.length)d.revealed=text.length;else if(d.index<d.lines.length-1){d.index++;d.revealed=0;}else if(!d.choices.length)closeDialogue();paintDialogue();}
function skipDialogue(){if(!dialogue)return;if(dialogue.choices.length){dialogue.index=dialogue.lines.length-1;dialogue.revealed=dialogue.lines[dialogue.index].length;paintDialogue();}else closeDialogue();}
function chooseDialogue(i){const c=dialogue?.choices[i];if(!c)return;closeDialogue();c.action();}
function closeDialogue(){document.body.classList.toggle('event-message',false);dialogue=null;$('#conversation').hidden=true;dialogueCooldown=20;renderer.domElement.focus({preventScroll:true});}
function milestone(id,who,lines){if(s.seen.includes(id))return;s.seen.push(id);}
function talkTo(target){if(target===capybara){capyTalk();return;}if(target?.userData.resident){residentStory(target);return;}if(target===visitorMesh){const v=s.visitor;if(v)showDialogue(v.name+' · '+v.job,[v.line,'이 섬에서 함께 살아도 될까요?'],[{label:'함께 살아요',action:acceptVisitor},{label:'다음에 만나요',action:declineVisitor}]);return;}if(target===board){setTab('events',true);return;}const r=target?.userData.resident;if(r){showDialogue(r.name+' · '+r.job,[`저는 ${r.job} 일이 익숙해요. ${s.weather==='rain'?'오늘은 비가 오네요. 우산을 챙겼어요.':'오늘도 우리 섬이 조금씩 달라지고 있네요.'}`,'어떤 일을 도와드릴까요?'],[{label:'🪵 벌목 부탁해요',action:()=>assignResident(r.id,'wood')},{label:'🪨 채광 부탁해요',action:()=>assignResident(r.id,'stone')},{label:'🍎 식량 수집 부탁해요',action:()=>assignResident(r.id,'food')},{label:'오늘은 쉬세요',action:()=>assignResident(r.id,null)}]);return;}if(animals.includes(target))showDialogue('숲속의 친구',[target.userData.kind==='bird'?'새가 둥지 곁에서 지저귀어요. 열매나무가 마음에 드나 봐요.':target.userData.kind==='deer'?'사슴이 연못에서 물을 마시고 고개를 들어 당신을 바라봐요.':'토끼가 가까이 다가와 코를 킁킁거려요. 이 섬이 편안한가 봐요.']);}
function nearbyTalk(){if(placement)return null;const targets=[capybara,visitorMesh,board,...npcs,...animals].filter(Boolean);return targets.find(o=>Math.hypot(o.position.x-player.position.x,o.position.z-player.position.z)<1.7);}
function eventValue(e){const state=s.events[e.id];if(!state)return 0;if(e.resource==='residents')return crew();if(e.resource==='mushroom')return state.count||0;return (s.totals[e.resource]||0)-(state.start||0);}
function eventAvailable(e){return e.id!=='rain'||s.rainCount>0;}
function takeEvent(id){const e=EVENT_DEFS.find(v=>v.id===id);if(!e||s.events[id]||!eventAvailable(e))return;s.events[id]={status:'active',start:s.totals[e.resource]||0,count:0};render();save();}
function claimEvent(id){const e=EVENT_DEFS.find(v=>v.id===id),state=s.events[id];if(!e||state?.status!=='active'||eventValue(e)<e.goal||!afford(e.pay))return false;pay(e.pay);storeItems(s,e.reward);state.status='claimed';if(e.decoration&&!s.decorations.includes(e.decoration))s.decorations.push(e.decoration);rebuildNature();render();save();toast('이벤트 완료!'+(e.decoration?' '+e.decoration+' 장식 획득':''));showReward(e.reward);beep(880);return true;}
function collectMushroom(){const p=s.mushrooms.find(p=>!p.collected&&Math.hypot(p.x-player.position.x,p.z-player.position.z)<1.8);return p?gatherMushroom(p):false;}
function produce(seconds=4){produceFor(s,seconds);s.colonyProgress=(s.colonyProgress||0)+seconds;if(s.colonyProgress>=60){s.colonyProgress%=60;for(const i of s.colonies){if(storageUsed(s)<storageCapacity(s))s[islands[i].type]++;}}}
const categories={nature:['🌳','자연·동물'],life:['🏠','집·생활'],production:['🪓','채집·생산'],people:['👥','주민'],sea:['⚓','항구·탐험'],events:['📜','게시판'],settings:['⚙️','설정']};tab='nature';let panelOpen=false;let bubbleTime=0,bubbleLeft=0,bubbleTarget=null;
function setTab(t,force=false){$('#detailDialog').close();cancelWork();closeActionMenu();if(tab===t&&!force)panelOpen=!panelOpen;else{if(tab!==t)lockedExpanded=false;tab=t;panelOpen=true;}render();}
let lockedExpanded=false;
function compactRow({icon,name,badge='',cost='',action='',detailKind='',id=''}){return `<article class="compact-row"><div class="row-title"><span class="row-icon">${icon}</span><b>${name}</b>${badge?`<small>${badge}</small>`:''}</div>${cost?`<div class="row-cost">${cost.split(' · ').map(token=>'<span>'+token.replaceAll(' ','')+'</span>').join('')}</div>`:''}<div class="row-actions">${action}<button class="detail-button" data-detail-kind="${detailKind}" data-detail-id="${id}" aria-label="${name} 자세히 보기">자세히 ⓘ</button></div></article>`;}
function buildingCard(d){const lv=level(s,d.id),req=requirements(s,d),cost=lv?lv<d.forms.length?upgradeCost(s,d):{}:d.cost;const locked=(!lv&&req.length)||(lv>0&&!upgradeAllowed(d,lv));const action=lv>=3?'<button disabled class="row-main complete">완성 ✓</button>':`<button class="row-main ${!locked&&afford(cost)?'ready':''}" ${locked||!afford(cost)||sea?'disabled':''} ${lv?`data-upgrade="${d.id}"`:`data-build="${d.id}"`}>${locked?'🔒 잠김':lv?'업그레이드':['boat','ship'].includes(d.id)?'구매':'건설'}</button>`;return compactRow({icon:d.icon,name:d.name,badge:lv?'Lv.'+lv:'',cost:costText(cost),action,detailKind:'building',id:d.id});}
function baseCompactPanel(){let html='';if(['nature','life','production','sea'].includes(tab)){if(tab==='nature')html+=compactRow({icon:'🌱',name:'열매나무',cost:costText({wood:4,food:2}),action:`<button id="plantTree" class="row-main" ${!afford({wood:4,food:2})||sea?'disabled':''}>심기</button>`,detailKind:'plant'});const list=defs.filter(d=>d.category===tab&&d.id!=='haven'&&(level(s,d.id)||(GATES[d.id]||0)<=havenLevel(s)+1)),available=list.filter(d=>level(s,d.id)||!requirements(s,d).length),locked=list.filter(d=>!level(s,d.id)&&requirements(s,d).length);html+=available.map(buildingCard).join('');if(locked.length)html+=`<details id="lockedBuildings" class="locked-list" ${lockedExpanded?'open':''}><summary>🔒 앞으로 열릴 건물 <span>${locked.length}</span></summary>${locked.map(buildingCard).join('')}</details>`;
if(tab==='life'&&level(s,'house')){html+=compactRow({icon:'🏡',name:'주택 추가',cost:costText(extraHomeCost()),action:`<button id="extraHome" class="row-main" ${!afford(extraHomeCost())||sea?'disabled':''}>건설</button>`,detailKind:'extra'});html+=s.homes.map((h,i)=>compactRow({icon:'🏠',name:'추가 주택 '+(i+1),badge:'Lv.'+h.level,cost:h.level<3?costText(upgradeCost(s,defs.find(d=>d.id==='house'),h.level)):'',action:h.level<3?`<button class="row-main" data-home-up="${h.id}" ${!afford(upgradeCost(s,defs.find(d=>d.id==='house'),h.level))||sea?'disabled':''}>업그레이드</button>`:'<button disabled class="row-main complete">완성 ✓</button>',detailKind:'home',id:h.id})).join('');}
if(tab==='sea'){if(!voyageUnlocked())html=compactRow({icon:'🔒',name:'항해 준비',badge:'중심 보금자리 7단계',detailKind:'sailing'})+html;else{html=compactRow({icon:'⛵',name:sea?'바다 탐험 중':'항해 준비',badge:`${sea?Math.ceil(hp):maxHP()}/${maxHP()}`,action:`<button id="sail" class="row-main ready" ${!level(s,'boat')?'disabled':''}>${sea?'귀항·수리':'출항'}</button>`,detailKind:'sailing'})+html;html+=islands.map((a,i)=>compactRow({icon:s.discovered.includes(i)?'🏝️':'🧭',name:s.discovered.includes(i)?a.name:'미지의 섬 '+(i+1),badge:s.colonies.includes(i)?'정착 ✓':'',cost:s.discovered.includes(i)&&!s.colonies.includes(i)?costText({wood:25,stone:15,food:10}):'',action:s.discovered.includes(i)&&!s.colonies.includes(i)?`<button class="row-main" data-colony="${i}" ${!sea||boat.position.distanceTo(new THREE.Vector3(a.x,0,a.z))>a.r+5||!afford({wood:25,stone:15,food:10})?'disabled':''}>정착</button>`:'',detailKind:'island',id:i})).join('');}}}
if(tab==='people'){html=`<div class="list-status">주민 ${crew()} / ${capacity(s)}명 · 빈방 ${Math.max(0,capacity(s)-crew())}</div>`;if(s.visitor)html+=compactRow({icon:'👋',name:s.visitor.name,badge:s.visitor.job,action:'<button id="greetVisitor" class="row-main ready">대화</button>',detailKind:'visitor'});if(!crew()&&!s.visitor)html=compactRow({icon:'🏡',name:'새 이웃 기다리기',badge:'주택 필요',detailKind:'residentsIntro'})+html;html+=s.residents.map(r=>compactRow({icon:'🧑',name:r.name,badge:r.job,action:`<button data-talk="${r.id}" class="row-main">대화</button><select aria-label="${r.name} 일 배정" data-resident="${r.id}"><option value="" ${!r.jobKey?'selected':''}>쉬기</option>${['wood','stone','food'].map(k=>`<option value="${k}" ${r.jobKey===k?'selected':''}>${names[k]}</option>`).join('')}</select>`,detailKind:'resident',id:r.id})).join('');}
if(tab==='events'){html=EVENT_DEFS.map(e=>{const state=s.events[e.id],v=eventValue(e),done=state?.status==='claimed';return compactRow({icon:e.id==='rain'?'🍄':'✉️',name:e.title,badge:done?'완료 ✓':state?Math.min(v,e.goal)+'/'+e.goal:'',cost:'🎁 '+costText(e.reward),action:done?'<button class="row-main complete" disabled>수령 ✓</button>':state?`<button class="row-main" data-claim="${e.id}" ${v<e.goal||!afford(e.pay)?'disabled':''}>보상 받기</button>`:`<button class="row-main" data-event="${e.id}" ${!eventAvailable(e)?'disabled':''}>${eventAvailable(e)?'참여':'🔒 비 온 뒤'}</button>`,detailKind:'event',id:e.id});}).join('');}
if(tab==='settings')html=compactRow({icon:'👑',name:'나의 주인공',badge:playerName(),action:'<button id="editCharacter" class="row-main">꾸미기</button>',detailKind:'character'})+`<article class="compact-row"><div class="row-title"><span class="row-icon">🎵</span><b>배경음악</b></div><div class="row-actions"><button id="toggleMusic" class="row-main">${s.audioOn?'끄기':'켜기'}</button><input id="volume" type="range" min="0" max="100" value="${s.volume*100}" aria-label="배경음악 음량"><button class="detail-button" data-detail-kind="settings" aria-label="설정 자세히 보기">자세히 ⓘ</button></div></article>`;return html;
}
function oldCompactPanel(){let html=baseCompactPanel();if(tab==='life')html=havenCard()+html;if(tab==='nature')html='<div class="life-links"><button data-life="decor">🌼 섬 꾸미기</button><button data-life="journal">📖 도감</button></div>'+html;if(tab==='production')html='<div class="life-links"><button data-life="trade:sell">🦫 카피의 상점</button><button data-life="bag">🎒 채집 가방</button></div>'+html;if(tab==='events')html=lifeEventsHTML()+html;return html;}
function compactPanel(){return menuTiles();}
function facilityEffect(id,lv){const effects={house:`입주 정원 ${lv*2}명 · 허락받은 이웃만 입주해요.`,cottages:`입주 정원 ${lv*4}명.`,habitat:'동물들이 쉬고 산책하는 터전.',orchard:'새들이 찾아오는 과수원.',pond:'사슴·물고기·개구리가 찾아와요.',farm:`식량 작업 ${1+lv*2}자리.`,lumber:`벌목 작업 ${1+lv*2}자리.`,quarry:`채석 작업 ${1+lv*2}자리.`,warehouse:`목재·석재·식량 보관 ${120+lv*180}개.`,store:'이웃들이 함께 식사하는 공간.',plaza:'이웃이 쉬고 만나는 공간.',council:`오프라인 최대 ${4+(lv-1)*2}시간 · 생산 효율 +${(lv-1)*10}%.`,dock:'금화로 탐험선을 구매하고 주변 섬을 발견해요.',boat:'평화로운 바다 탐험과 새로운 섬 발견.',ship:'더 빠르게 먼 바다를 탐험해요.',fishing:'처음부터 이용 가능 · 발전하면 새로운 어획물이 찾아와요.'};return effects[id]||'';}

function showDetails(kind,id=''){$('#detailMaterial').hidden=true;if(['building','home'].includes(kind)&&id!=='haven'){showCompactBuilding(kind,id);return;}if(id==='haven'){showHaven();return;}let title='',body='',actions=[];
if(kind==='building'||kind==='home'){const h=kind==='home'?s.homes.find(h=>h.id===id):null,d=defs.find(d=>d.id===(h?'house':id));if(!d)return;const lv=h?h.level:level(s,d.id),req=requirements(s,d);title=d.icon+' '+(h?'추가 주택':d.name);body=`<p>${d.desc}</p><div class="detail-levels">${d.forms.map((form,i)=>`<span class="${lv===i+1?'current':''}">${i+1}단계 · ${form}</span>`).join('')}</div>`;if(lv){body+=`<h3>현재 효과</h3><p>${facilityEffect(d.id,lv)}</p>`;if(lv<3){const cost=upgradeCost(s,d,lv);body+=`<h3>다음 단계</h3><p>${facilityEffect(d.id,lv+1)}</p><div class="detail-cost">${costText(cost)}</div>`;actions.push({label:'업그레이드',disabled:!upgradeAllowed(d,lv)||!afford(cost)||sea,action:()=>upgrade(d.id,h?.id)});}if(!['boat','ship'].includes(d.id))actions.push({label:'위치·방향 바꾸기',disabled:sea,action:()=>startPlacement(d.id,'move',h?.id)});}else{body+=`<h3>필요 재료</h3><div class="detail-cost">${costText(d.cost)}</div><h3>건설 조건</h3><p>${req.length?req.map(([id,n])=>defs.find(d=>d.id===id).name+' '+n+'단계').join(' + '):'지금 건설할 수 있어요.'}</p><p>${facilityEffect(d.id,1)}</p>`;actions.push({label:['boat','ship'].includes(id)?'금화로 구매':'위치 정하고 건설',disabled:!!req.length||!afford(d.cost)||sea,action:()=>build(d.id)});}}
else if(kind==='event'){const e=EVENT_DEFS.find(e=>e.id===id);if(!e)return;title='📜 '+e.title;body=`<p>${e.giver}</p><p>${e.text}</p><h3>참여 방법</h3><p>참여를 누른 뒤 목표를 달성하고, 보상 받기를 눌러 주세요. 자원은 참여 후 직접 수집한 양을 셉니다. 참여하지 않아도 기본 성장은 가능해요.</p>${Object.keys(e.pay).length?'<p>완료 시 기부 '+costText(e.pay)+'</p>':''}<h3>완료 보상</h3><p>${costText(e.reward)}${e.decoration?' · '+e.decoration+' 장식':''}</p>`;}
else if(kind==='plant'){title='🌱 열매나무';body='<p>나무를 심으면 섬에 새로운 터전이 생겨요. 30초 뒤 둥지가 생기고 새가 찾아옵니다. 나무는 섬 안에서 건물과 겹치지 않는 곳에 심을 수 있어요.</p><h3>필요 재료</h3><div class="detail-cost">🪵 4 · 🍎 2</div>';actions.push({label:'심을 위치 정하기',disabled:!afford({wood:4,food:2})||sea,action:()=>startPlacement('sapling','plant')});}
else if(kind==='extra'){title='🏡 주민 주택 추가';body=`<p>새 주택 한 채마다 방 2개가 생겨요. 3단계까지 업그레이드하면 6명이 살 수 있어요. 빈방이 있으면 방문자가 찾아오고, 대화로 허락한 뒤 정착해요.</p><div class="detail-cost">${costText(extraHomeCost())}</div>`;actions.push({label:'새 주택 건설',disabled:!afford(extraHomeCost())||sea,action:()=>startPlacement('house','extra')});}
else if(kind==='resident'||kind==='visitor'||kind==='residentsIntro'){const r=kind==='resident'?s.residents.find(r=>r.id===+id):s.visitor;title=r?'👋 '+r.name+' · '+r.job:'👥 새로운 이웃';body=r?`<p>${r.line}</p><p>특기에 맞는 일을 맡기면 생산량 +1. 일은 대화 또는 목록의 간편 배정으로 부탁할 수 있어요.</p>`:'<p>주민 주택을 짓고 업그레이드해 빈방을 마련하세요. 입주 희망자는 45초 간격으로 방문하고, 주택이 완성되면 첫 방문자가 바로 찾아옵니다. 허락받은 사람만 주민이 돼요.</p>';}
else if(kind==='sailing'){title='⚓ 항구와 탐험';body='<p>중심 보금자리 큰집(7단계)에서 항구가 열려요. 항구를 건설하면 금화 80으로 탐험선을 구매합니다. 빌라(8단계)·항구 3단계·탐험선 2단계에서 대형선이 열려요.</p><p>출항 후 바다를 눌러 항해해요. 새로운 섬을 발견하면 수정과 금화를 받고 평화롭게 정착할 수 있어요.</p>';}
else if(kind==='island'){const a=islands[+id];title='🏝️ '+(s.discovered.includes(+id)?a.name:'미지의 섬');body=`<p>${s.discovered.includes(+id)?a.desc:['서북쪽 바다를 탐험해 보세요.','동북쪽 바다를 탐험해 보세요.','남쪽 바다를 탐험해 보세요.'][+id]}</p><p>발견한 섬 가까이에서 재료를 사용해 정착할 수 있어요.</p>`;}
else if(kind==='character'){title='👑 '+playerName();body='<p>아이의 그림에서 태어난 주인공입니다. 노란 X와 왕관, 작은 날개가 특징이에요.</p><p>현재 주인공은 1종, 옷과 왕관은 각 2가지 색을 고를 수 있어요. 꾸미기는 섬 진행 상황을 그대로 유지합니다.</p>';}
else{title='🌙 섬의 시간과 소리';body='<p>섬의 하루는 실제 20분이에요. 낮·노을·밤에 맞춰 음악이 부드럽게 달라집니다. 비가 오면 빗소리가 섞여요.</p><p>음악은 켜기를 눌러 시작하고 음량 막대로 조절할 수 있어요. PC는 마우스 휠, 모바일은 두 손가락으로 캐릭터를 중심으로 확대·축소해요.</p>';}
if(kind==='event'){const e=EVENT_DEFS.find(e=>e.id===id),st=s.events[id];actions.push({label:st?.status==='claimed'?'완료':st?'보상 받기':'참여하기',disabled:st?.status==='claimed'||(!!st&&(eventValue(e)<e.goal||!afford(e.pay))),action:()=>{if(st)claimEvent(id);else takeEvent(id);}});}
if(kind==='sailing')actions.push({label:sea?'귀항하기':'출항하기',disabled:!level(s,'boat')||!voyageUnlocked(),action:sail});
if(kind==='island'){const a=islands[Number(id)];actions.push({label:'정착지 건설',disabled:!sea||!s.discovered.includes(+id)||s.colonies.includes(+id)||boat.position.distanceTo(new THREE.Vector3(a.x,0,a.z))>a.r+5||!afford({wood:25,stone:15,food:10}),action:()=>colonize(+id)});}
if(kind==='character')actions.push({label:'꾸미기',action:openAvatarEditor});
$('#detailTitle').textContent=title;$('#detailBody').innerHTML=body;$('#detailActions').innerHTML=actions.map((a,i)=>`<button data-detail-action="${i}" ${a.disabled?'disabled':''} class="${i===0?'primary':''}">${a.label}</button>`).join('');$('#detailActions').querySelectorAll('[data-detail-action]').forEach(b=>b.onclick=()=>{const a=actions[+b.dataset.detailAction];if(!a.disabled){$('#detailDialog').close();a.action();}});openDetail();cancelMove();clearKeys();}
$('#closeDetail').onclick=()=>{$('#detailDialog').close();renderer.domElement.focus({preventScroll:true});};

