const objectReactions=[];
function reactObject(object,kind='shake'){if(!object?.parent)return;let fx=objectReactions.find(f=>f.object===object);if(fx){object.scale.copy(fx.scale);object.rotation.z=fx.z;objectReactions.splice(objectReactions.indexOf(fx),1);}fx={object,kind,scale:object.scale.clone(),z:object.rotation.z,left:kind==='build'?2.4:.4,total:kind==='build'?2.4:.4};objectReactions.push(fx);}
function startAction(kind,target=null,position=null){if(kind!=='wave')standUp();const r=player.userData.rig;if(!r)return;r.actionKind=kind;r.actionTotal=kind==='wave'?1.4:kind==='cheer'?2.4:.65;r.action=r.actionTotal;r.actionHit=false;r.actionTarget=target;r.actionPosition=position?.clone()||target?.position.clone()||player.position.clone();if(['wood','stone'].includes(kind))actionTool(r,kind);}
function actionImpact(r){if(r.actionHit)return;r.actionHit=true;const kind=r.actionKind;if(['wood','stone','food','pick'].includes(kind)){const pos=r.actionPosition.clone();pos.y=kind==='stone'?.9:kind==='wood'?1.5:1;burst(pos,kind==='pick'?'food':kind,kind==='stone'?12:9);reactObject(r.actionTarget);}}
function constructionEffect(id,homeId=null){actionMenuUntil=elapsed+2.4;const object=buildingGroups.get(homeId||id)||(['boat','ship'].includes(id)?boat:null);if(!object)return;const p=object.position.clone();p.y=1;burst(p,'build',18);ripple(p);reactObject(object,'build');startAction('cheer');}
function updateEffects(dt){for(let i=actionFX.length-1;i>=0;i--){const f=actionFX[i];f.life-=dt;if(f.life<=0){f.mesh.removeFromParent();f.mesh.material.dispose();actionFX.splice(i,1);continue;}f.velocity.y-=5*dt;f.mesh.position.addScaledVector(f.velocity,dt);f.mesh.material.opacity=Math.min(.9,f.life*2);f.mesh.scale.multiplyScalar(Math.exp(-dt*.8));}for(let i=actionBursts.length-1;i>=0;i--){const f=actionBursts[i];f.life-=dt;if(f.life<=0){f.mesh.removeFromParent();f.mesh.material.dispose();actionBursts.splice(i,1);continue;}f.mesh.scale.setScalar(.3+(1-f.life/f.total)*3);f.mesh.material.opacity=f.life/f.total*.65;}for(let i=objectReactions.length-1;i>=0;i--){const f=objectReactions[i];f.left=Math.max(0,f.left-dt);const t=1-f.left/f.total;if(!f.object.parent||f.left<=0){f.object.scale.copy(f.scale);f.object.rotation.z=f.z;objectReactions.splice(i,1);continue;}if(f.kind==='build'){const pop=1+Math.sin(t*Math.PI*2)*.12*(1-t);f.object.scale.copy(f.scale).multiplyScalar(pop);}else{f.object.rotation.z=f.z+Math.sin(t*Math.PI*4)*.07*(1-t);f.object.scale.copy(f.scale).multiplyScalar(1-Math.sin(t*Math.PI)*.055);}}}

// Island life: all durable outcomes commit once, after a completed action.
let workTask=null,fishState=null,pitch=.62,lastY=0,lifeTick=0,capybara=null,havenMesh=null,lifeFlames=[],lifeDecorObjects=new Map(),beachObjects=new Map(),seaLife=[];
const lifeGroup=new THREE.Group();scene.add(lifeGroup);
const itemInfo=key=>CATCHES.find(c=>c.id===key)||({name:names[key]||key,icon:icons[key]||'✦'});
function fullCost(cost,counts=false){return Object.entries(cost).map(([k,n])=>{const c=itemInfo(k);return `${c.icon} ${counts?Math.floor(itemCount(s,k))+'/':''}${n}`;}).join(' · ');}
function upgradeAllowed(d,lv){if(d.id==='dock'&&lv===2)return havenLevel(s)>=8;return d.id==='haven'||havenLevel(s)>=(lv===1?4:6)||(['boat','ship'].includes(d.id)&&havenLevel(s)>=7);}
function discover(id){if(s.discoveries[id])return false;s.discoveries[id]=Math.floor(s.time/1200)+1;return true;}
function gainItems(items){storeItems(s,items);showReward(items);}
function cancelWork(){if(fishState)endFishingView();if(workTask||fishState){workTask=null;fishState=null;$('#actionProgress').hidden=true;$('#fishReel').hidden=true;$('#fishCancel').hidden=true;const r=player.userData.rig;r.action=0;r.actionTarget=null;if(r.tools)Object.values(r.tools).forEach(t=>t.visible=false);if(r.rod)r.rod.visible=false;if(fishingFloat)fishingFloat.visible=false;}}
function beginWork(kind,duration,position,complete,object=null){if(workTask||fishState)return false;cancelMove();clearKeys();stopJoystick();const origin=player.position.clone();if(position)player.rotation.y=Math.atan2(position.x-origin.x,position.z-origin.z);workTask={kind,duration,left:duration,complete,origin,position:position?.clone()||origin,object,beat:0};startAction(kind==='mushroom'||kind==='beach'?'pick':kind,object,position);const r=player.userData.rig;r.actionTotal=duration;r.action=duration;$('#actionProgress').hidden=false;return true;}
function updateWork(dt){if(fishState){updateFishing(dt);return;}if(!workTask)return;const w=workTask;if(sea||dialogue||placement||player.position.distanceTo(w.origin)>.12){cancelWork();return;}w.left=Math.max(0,w.left-dt);paintWork(w.kind,w.left,w.duration,w.position);const beat=Math.floor((w.duration-w.left)/1.1);if(beat>w.beat){w.beat=beat;if(w.object)reactObject(w.object);beep(w.kind==='stone'?220:330);}if(w.left<=0){workTask=null;$('#actionProgress').hidden=true;player.userData.rig.action=0;w.complete();render();save();}}
function paintWork(kind,left,total,position){const p=position.clone();p.y=2.5;p.project(camera);const ui=$('#actionProgress');ui.style.left=THREE.MathUtils.clamp((p.x+1)*viewWidth/2,90,viewWidth-90)+'px';ui.style.top=THREE.MathUtils.clamp((1-p.y)*viewHeight/2,65,viewHeight-115)+'px';$('#actionLabel').textContent=['cast','wait','bite','reel'].includes(kind)?'잡는중':['build'].includes(kind)?'건설중':kind==='upgrade'?'발전중':'채집중';$('#actionMeter').style.width=Math.max(0,Math.min(100,(1-left/total)*100))+'%';}
function oldCollectResource(r){if(workTask||fishState)return false;if(!resources.includes(r)||!r.g.visible||sea||Math.hypot(r.x-player.position.x,r.z-player.position.z)>2.1||r.cool>0)return false;return beginWork(r.type,r.type==='food'?2:3,r.g.position,()=>{if(!r.g.visible)return;r.cool=.3;s[r.type]++;s.totals[r.type]++;showReward({[r.type]:1});beep(440);},r.g);}
function collectResource(r){if(workTask||fishState||!resources.includes(r)||!r.g.visible||sea||Math.hypot(r.x-player.position.x,r.z-player.position.z)>2.1||r.cool>0||r.remaining<=0)return false;const started=beginWork(r.type,r.type==='food'?2:3,r.g.position,()=>{if(!resources.includes(r)||!r.g.visible||r.remaining<=0)return;const amount=Math.min(r.remaining,1+skillBonus('gather'));r.remaining-=amount;r.cool=.3;gainItems({[r.type]:amount});s.totals[r.type]+=amount;awardSkill('gather');removeSpentNode(r);beep(440);},r.g);if(started)workTask.resourceRef=r;return started;}
function collectShroom(p){if(workTask||fishState||p.collected||!s.mushrooms.includes(p)||Math.hypot(p.x-player.position.x,p.z-player.position.z)>1.8)return false;return beginWork('mushroom',2,new THREE.Vector3(p.x,0,p.z),()=>{if(p.collected)return;p.collected=true;const amount=1+skillBonus('gather');gainItems({food:amount});awardSkill('gather');if(s.events.rain?.status==='active')s.events.rain.count++;showReward({food:amount});rebuildNature();});}
function collectTree(p,chop=false){if(workTask||fishState||!s.saplings.includes(p)||Math.hypot(p.x-player.position.x,p.z-player.position.z)>2.1||(!chop&&(p.age<30||s.time<(p.fruitReadyAt||0))))return false;return beginWork(chop?'wood':'food',chop?3:2,new THREE.Vector3(p.x,0,p.z),()=>{if(chop){s.saplings.splice(s.saplings.indexOf(p),1);s.wood++;s.totals.wood++;}else{s.food++;s.totals.food++;p.fruitReadyAt=s.time+10;}showReward({[chop?'wood':'food']:1});awardSkill('gather');rebuildNature();},saplingObjects.get(p));}
function lifeDialog(title,html,buttons=[]){$('#detailDialog').classList.toggle('keypad-open',false);$('#detailMaterial').hidden=true;cancelMove();clearKeys();resetGesture();$('#detailTitle').textContent=title;$('#detailBody').innerHTML=html;$('#detailActions').innerHTML=buttons.map((b,i)=>`<button data-life-choice="${i}" ${b.disabled?'disabled':''} class="${i===0?'primary':''}">${b.label}</button>`).join('');$('#detailActions').querySelectorAll('[data-life-choice]').forEach(b=>b.onclick=()=>{const a=buttons[+b.dataset.lifeChoice];if(!a.disabled){$('#detailDialog').close();a.action();}});openDetail();bindLifeButtons($('#detailBody'));}
function capyTalk(){showDialogue('카피 · 카피바라 상인',[playerName()+'! 왔구나. 오늘은 뭘 모았어? 천천히 해도 괜찮아.'],[{label:'재료 사고팔기',action:()=>showTrade()},{label:'이야기 나누기',action:()=>befriend(false)},{label:'물고기 선물하기',action:()=>befriend(true)},{label:'발견 도감',action:showJournal}]);}
function befriend(gift){const day=Math.floor(s.time/1200),key=(gift?'gift':'talk')+day;if(s.friendActions[key]){showDialogue('카피',['오늘도 함께 있어 줘서 고마워. 선물과 이야기 보너스는 내일 다시 받을 수 있어.']);return;}if(gift){const c=CATCHES.find(c=>['minnow','seabass','moonfish'].includes(c.id)&&s.items[c.id]>0);if(!c){toast('물고기를 한 마리 낚아 선물해 주세요.');return;}s.items[c.id]--;}s.friendActions[key]=true;s.friendship+=gift?2:1;const gifts=[];s.decorTokens??={};for(const [n,k]of [[3,'flowers'],[6,'bench'],[10,'lamp']])if(s.friendship>=n&&!s.friendGifts.includes(n)){s.friendGifts.push(n);s.decorTokens[k]=(s.decorTokens[k]||0)+1;gifts.push(DECOR.find(d=>d.id===k).name);}showDialogue('카피',[s.friendship>=6?'이젠 네가 오면 나도 모르게 웃게 돼. 여긴 우리 둘의 집이기도 하니까.':'모닥불에서 시작해서, 조금씩 우리만의 섬을 만들어 보자.',`친밀도 ${s.friendship}${gifts.length?' · 선물: '+gifts.join(', ')+' (꾸미기에서 무료 배치)':''}`]);render();save();}
let tradeMode='sell',tradeItem='wood',tradeAmount=1,keypadDraft='',keypadFresh=true;
function tradeMaximum(){return Math.max(0,Math.min(999,tradeMode==='buy'?Math.floor(s.gold/(PRICES[tradeItem]*3)):itemCount(s,tradeItem)));}
function showTrade(mode='sell',key=tradeItem){tradeMode=mode;const keys=mode==='buy'?['wood','stone','food','seaweed','shell','scrap']:Object.keys(PRICES);tradeItem=keys.includes(key)?key:keys[0];tradeAmount=Math.min(Math.max(1,tradeAmount),Math.max(1,tradeMaximum()));const selected=itemInfo(tradeItem);lifeDialog('🦫 카피의 작은 상점',`<div class="life-tabs"><button data-life="trade:sell">팔기</button><button data-life="trade:buy">사기</button><button data-life="surplus">필요량 남기고 판매</button></div><div class="life-grid">${keys.map(k=>{const d=itemInfo(k);return `<button data-life="selecttrade:${k}" aria-pressed="${k===tradeItem}">${d.icon} ${d.name}<small>${itemCount(s,k)}개 · 🪙${PRICES[k]*(mode==='buy'?3:1)}</small></button>`;}).join('')}</div><div class="trade-controls"><b>${selected.icon} ${selected.name}</b><button id="quantityMinus" aria-label="수량 줄이기">−</button><button id="tradeQuantity" aria-label="수량 입력">${tradeAmount}</button><button id="quantityPlus" aria-label="수량 늘리기">+</button><button id="quantityMax">최대</button></div><div id="gameKeypad" hidden><output id="keypadValue"></output><div class="keypad-grid">${['1','2','3','4','5','6','7','8','9','지우기','0','확인'].map(k=>`<button data-digit="${k}">${k}</button>`).join('')}</div><button id="keypadCancel">취소</button></div>`,[{label:(mode==='buy'?'구매':'판매')+' · 🪙'+tradeAmount*PRICES[tradeItem]*(mode==='buy'?3:1),disabled:tradeMaximum()<tradeAmount,action:()=>doTrade(mode,tradeItem,tradeAmount)}]);$('#quantityMinus').onclick=()=>{tradeAmount=Math.max(1,tradeAmount-1);showTrade(mode);};$('#quantityPlus').onclick=()=>{tradeAmount=Math.min(Math.max(1,tradeMaximum()),tradeAmount+1);showTrade(mode);};$('#quantityMax').onclick=()=>{tradeAmount=Math.max(1,tradeMaximum());showTrade(mode);};$('#tradeQuantity').onclick=()=>{keypadDraft=String(tradeAmount);keypadFresh=true;$('#detailDialog').classList.toggle('keypad-open',true);$('#gameKeypad').hidden=false;$('#keypadValue').textContent=keypadDraft;};$('#keypadCancel').onclick=()=>{showTrade(tradeMode);};$('#gameKeypad').querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>pressTradeDigit(b.dataset.digit));}
function pressTradeDigit(key){if(/^\d$/.test(key)&&keypadFresh){keypadDraft='';keypadFresh=false;}if(key==='확인'){tradeAmount=Math.max(1,Math.min(tradeMaximum(),Number(keypadDraft)||1));showTrade(tradeMode);return;}keypadDraft=key==='지우기'?keypadDraft.slice(0,-1):/^\d$/.test(key)?(keypadDraft==='0'?'':keypadDraft)+key:keypadDraft;keypadDraft=keypadDraft.slice(0,3);$('#keypadValue').textContent=keypadDraft||'0';}

function doTrade(mode,key,quantity){if(mode==='sell'&&['moonfish','chest','crystal'].includes(key)&&!confirm('귀한 '+itemInfo(key).name+'을 판매할까요?'))return false;const previousAmount=itemCount(s,key);if(!exchange(s,key,quantity,mode==='buy')){toast('수량과 보유 재료·금화를 확인해 주세요.');return false;}if(mode==='buy'&&['wood','stone','food'].includes(key)){s[key]=previousAmount;storeItems(s,{[key]:Number(quantity)});}save();render();showTrade(mode);toast(mode==='buy'?'필요한 재료를 챙겼어요.':'카피가 재료를 사고 금화를 건넸어요.');return true;}
function showBag(){lifeDialog('🎒 채집 가방',`<p>낚시 재료는 보금자리 발전·시설 업그레이드·게시판 부탁에 사용해요.</p><div class="life-grid">${CATCHES.map(c=>`<article class="bag-item"><b>${c.icon} ${c.name} ×${s.items[c.id]}</b><small>${c.desc}</small>${['minnow','seabass','driftwood','chest'].includes(c.id)?`<button data-life="use:${c.id}" ${s.items[c.id]<1?'disabled':''}>${c.id==='chest'?'상자 열기':c.id==='driftwood'?'목재 2개로 손질':'식량 2개로 준비'}</button>`:''}</article>`).join('')}</div>`);}
function useCatch(id){if(!['minnow','seabass','driftwood','chest'].includes(id)||s.items[id]<1)return false;s.items[id]--;gainItems(id==='chest'?{wood:3,stone:2,gold:10}:id==='driftwood'?{wood:2}:{food:2});save();render();showBag();return true;}
function havenCard(){const lv=havenLevel(s),next=HAVENS[lv];return `<article class="compact-row haven-row"><div class="row-title"><span class="row-icon">${HAVENS[Math.max(0,lv-1)].icon}</span><b>${lv?HAVENS[lv-1].name:'중심 보금자리'}</b><small>${lv}/8</small></div><div class="row-actions"><button data-life="haven" class="row-main">${lv===8?'성장 기록':lv?'다음 보금자리':'모닥불 만들기'}</button><button data-life="decor" class="detail-button">꾸미기</button></div></article>`;}
function showHaven(){const lv=havenLevel(s),next=HAVENS[lv];lifeDialog('🔥 우리의 중심 보금자리',`<div class="haven-path">${HAVENS.map((h,i)=>`<span class="${i<lv?'reached':''}">${h.icon} ${h.name}</span>`).join('')}</div><p>${next?next.name+'에서 열리는 것: '+next.unlock:'모든 보금자리 단계가 열렸어요. 이제 마음껏 섬을 가꿔요.'}</p>${next?'<p>'+fullCost(next.cost,true)+'</p>':''}`,[...(next?[{label:lv?'다음 단계로 발전':'모닥불 위치 정하기',disabled:!canPay(s,next.cost),action:()=>lv?upgrade('haven'):build('haven')}]:[]),{label:'카피에게 재료 거래',action:()=>showTrade()}]);}
function nextGoal(){const steps=[['haven',1],['habitat',1],['haven',2],['fishing',1],['haven',3],['house',1],['farm',1],['haven',4],['lumber',1],['quarry',1],['haven',5],['warehouse',1],['haven',6],['council',1],['haven',7],['dock',1],['boat',1],['haven',8],['dock',3],['boat',2],['ship',1]];let step=steps.find(([id,n])=>level(s,id)<n);if(!step)return {title:'우리만의 섬 꾸미기',desc:'카피와 친해지고, 도감을 채우고, 이웃의 부탁을 들어보세요.',cost:{},action:showDecor};const [id,n]=step,d=defs.find(d=>d.id===id),lv=level(s,id),cost=lv?upgradeCost(s,d,lv):d.cost,name=id==='haven'?HAVENS[lv].name:lv?d.name+' '+(lv+1)+'단계':d.name,ready=canPay(s,cost);return {title:(ready?'':id==='boat'||id==='ship'?'배 살 금화 모으기 · ':'재료 모으기 · ')+name+(ready?(lv?'로 발전하기':id==='boat'||id==='ship'?' 구매하기':' 만들기'):''),desc:ready?'준비가 끝났어요. 목표를 눌러 다음 이야기를 시작해요.':Object.keys(cost).some(k=>k in s.items)?'낚시터에서 재료를 낚거나 카피에게 구매할 수 있어요.':'직접 모으거나 카피와 거래해 필요한 재료를 준비해요.',cost,action:()=>ready?(lv?upgrade(id):build(id)):(id==='boat'||id==='ship'?showTrade():id==='haven'?showHaven():showDetails('building',id))};}
function paintGoal(){const g=nextGoal();$('#questTitle').textContent=g.title;$('#questText').textContent=g.desc;$('#questProgress').textContent=fullCost(g.cost,true)||'느긋하게, 우리만의 섬';const e=Object.entries(g.cost);$('#progress').style.width=(e.length?e.reduce((a,[k,n])=>a+Math.min(1,itemCount(s,k)/n),0)/e.length*100:100)+'%';$('#questGo').textContent=canPay(s,g.cost)?'다음 행동 →':'준비 살펴보기';$('#questGo').onclick=g.action;}
let decorCostsVisible=false;
function showDecor(){lifeDialog('🌼 섬 꾸미기',`<div class="life-grid decor-picker">${DECOR.map(d=>`<button data-life="place:${d.id}" aria-label="${d.name} · ${fullCost(d.cost)}"><span>${d.icon}</span><b>${d.name}</b><small class="decor-cost" ${decorCostsVisible?'':'hidden'}>${s.decorTokens?.[d.id]?'선물 · 무료':fullCost(d.cost)}</small></button>`).join('')}</div>`);$('#detailMaterial').hidden=false;$('#detailMaterial').textContent=decorCostsVisible?'재료 접기':'ⓘ 재료';$('#detailMaterial').setAttribute('aria-expanded',String(decorCostsVisible));$('#detailMaterial').onclick=()=>{decorCostsVisible=!decorCostsVisible;showDecor();};}


const ANIMAL_BOOK=[{id:'animal-rabbit',name:'숲속 토끼',icon:'🐰',desc:'작은 먹이터를 좋아해요.'},{id:'animal-bird',name:'섬의 새',icon:'🐦',desc:'열매나무에서 노래해요.'},{id:'animal-deer',name:'물가의 사슴',icon:'🦌',desc:'연못 곁을 천천히 걸어요.'},{id:'capy',name:'카피',icon:'🦫',desc:'처음부터 곁에 있던 카피바라 친구.'},{id:'letter',name:'편지병',icon:'💌',desc:'바다를 건너온 작은 부탁.'},{id:'beach-shell',name:'해변 조개',icon:'🐚',desc:'모래 위에서 만난 선물.'},{id:'beach-wood',name:'떠밀려온 나무',icon:'🪵',desc:'파도가 두고 간 나무 조각.'}];
function showJournal(){const entries=[...CATCHES,...ANIMAL_BOOK],n=Object.keys(s.discoveries).length;lifeDialog('📖 섬의 발견 도감',`<p>발견 ${n}/${entries.length} · 처음 발견한 날을 기록해요.</p><div class="book-grid">${entries.map(c=>`<article class="${s.discoveries[c.id]?'found':'unknown'}"><b>${s.discoveries[c.id]?c.icon+' '+c.name:'❔ 아직 만나지 못했어요'}</b><small>${s.discoveries[c.id]?c.desc+' · '+s.discoveries[c.id]+'일째':''}</small></article>`).join('')}</div>`,[{label:'도감 선물 받기 (5종마다)',disabled:Math.floor(n/5)<=s.collectionRewards.length,action:()=>{const tier=Math.floor(Object.keys(s.discoveries).length/5);if(tier<=s.collectionRewards.length)return;s.collectionRewards.push(s.collectionRewards.length+1);s.decorTokens??={};s.decorTokens.lamp=(s.decorTokens.lamp||0)+1;save();toast('발견을 기념하는 섬 조명을 받았어요!');showJournal();}}]);}
function requestFor(r){const i=s.residents.findIndex(x=>x.id===r.id);const all=[{kind:'flowers',text:'집 앞에서 꽃을 구경하고 싶어요. 들꽃 화단 하나를 심어줄래요?',need:()=>s.decorPlaced.some(d=>d.kind==='flowers'),pay:{}},{kind:'fish',text:'오늘은 물고기 요리를 해보고 싶어요. 작은물고기 한 마리 부탁해요.',need:()=>s.items.minnow>=1,pay:{minnow:1}},{kind:'bench',text:'산책하다 잠깐 쉴 수 있는 벤치가 있으면 좋겠어요.',need:()=>s.decorPlaced.some(d=>d.kind==='bench'),pay:{}}];return all[Math.max(0,i)%all.length];}
function residentStory(target){const r=target.userData.resident,i=s.residents.indexOf(r),p=PERSONALITIES[Math.max(0,i)%4];showDialogue(r.name+' · '+p.name,[p.phrase], [{label:'작은 부탁',action:()=>showResidentRequest(r)},{label:'일 부탁하기',action:()=>showDialogue(r.name,['어떤 일을 도와드릴까요?'],['wood','stone','food',null].map(k=>({label:k?(icons[k]+' '+names[k]+' 수집'):'오늘은 쉬세요',action:()=>assignResident(r.id,k)})))},{label:'선물 주기',action:()=>{const key='resident-'+r.id+'-'+Math.floor(s.time/1200);if(s.friendActions[key]||s.food<1){toast('오늘 선물을 줬거나 식량이 부족해요.');return;}s.food--;s.friendActions[key]=true;r.friendship=(r.friendship||0)+1;save();showDialogue(r.name,['고마워요. 이 섬에서 함께 지내서 기뻐요.']);}}]);}
function progressResidentRequest(r){const q=requestFor(r),state=s.residentRequests[r.id];if(state==='done')return false;if(!state){s.residentRequests[r.id]='active';save();return true;}if(!q.need()||!spend(s,q.pay))return false;s.residentRequests[r.id]='done';gainItems({gold:8,food:2});toast(r.name+' 님이 고마워해요!');save();render();return true;}
function showResidentRequest(r){const q=requestFor(r),state=s.residentRequests[r.id];lifeDialog('💌 '+r.name+'의 작은 부탁',`<p>${q.text}</p><p>${state==='done'?'이미 고마운 마음을 전했어요.':'보상: 금화 8 · 식량 2'}</p>`,[{label:state==='done'?'완료한 부탁':state==='active'?'부탁 완료하기':'부탁 들어주기',disabled:state==='done'||(state==='active'&&!q.need()),action:()=>{progressResidentRequest(r);showResidentRequest(r);}}]);}
const LIFE_EVENTS=[{id:'clean',name:'파도에게 돌려주는 깨끗한 바다',text:'쓰레기 대신 쓸모 있는 재활용 조각 3개를 모아 기부해요.',need:()=>s.items.scrap>=3,pay:{scrap:3},reward:{gold:20,wood:5}},{id:'fish',name:'카피와 나누는 물고기 저녁',text:'작은물고기 2마리를 모아 저녁 식탁에 나눠요.',need:()=>s.items.minnow>=2,pay:{minnow:2},reward:{gold:18,food:5}},{id:'letter',name:'바다 건너온 화단 부탁',text:'편지병을 발견하고 섬에 들꽃 화단을 하나 놓아요.',need:()=>s.lettersFound>0&&s.decorPlaced.some(d=>d.kind==='flowers'),pay:{},reward:{gold:15,shell:1}}];
function lifeEventsHTML(){return `<div class="life-links"><button data-life="journal">📖 발견 도감</button><button data-life="beach">💌 해변 소식</button></div>`+LIFE_EVENTS.map(e=>`<article class="compact-row"><div class="row-title"><b>${e.name}</b><small>${s.lifeEvents[e.id]==='done'?'완료':s.lifeEvents[e.id]?'참여 중':''}</small></div><div class="row-actions"><button class="row-main" data-life="event:${e.id}">${s.lifeEvents[e.id]==='done'?'살펴보기':'참여·보상'}</button></div></article>`).join('');}
function progressLifeEvent(id){const e=LIFE_EVENTS.find(e=>e.id===id),state=s.lifeEvents[id];if(!e||state==='done')return false;if(!state){s.lifeEvents[id]='active';save();return true;}if(!e.need()||!spend(s,e.pay))return false;s.lifeEvents[id]='done';gainItems(e.reward);toast('작은 부탁을 완성했어요!');save();render();return true;}
function showLifeEvent(id){const e=LIFE_EVENTS.find(e=>e.id===id);if(!e)return;const state=s.lifeEvents[id];lifeDialog('📜 '+e.name,`<p class="event-summary">${e.text}</p><p>선물 ${fullCost(e.reward)}</p><p>${state==='done'?'보상을 이미 받았어요.':fullCost(e.pay,true)}</p>`,[{label:state==='done'?'완료':state==='active'?'완료하고 보상 받기':'이벤트 참여',disabled:state==='done'||(state==='active'&&!e.need()),action:()=>{progressLifeEvent(id);showLifeEvent(id);}}]);}
function bindLifeButtons(root){root.querySelectorAll('[data-life]').forEach(b=>b.onclick=()=>{const [action,a,k]=b.dataset.life.split(':');if(action==='surplus')sellSurplus();if(action==='bag')showBag();if(action==='use')useCatch(a);if(action==='trade')showTrade(a);if(action==='selecttrade'){tradeAmount=1;showTrade(tradeMode,a);}if(action==='haven')showHaven();if(action==='decor')showDecor();if(action==='journal')showJournal();if(action==='place'){$('#detailDialog').close();startPlacement('decor:'+a,'decor');}if(action==='event')showLifeEvent(a);if(action==='beach')lifeDialog('💌 파도가 두고 간 선물',['해변에 가끔 편지병·조개·유목이 떠밀려와요.','편지병에서 발견한 부탁은 게시판에서 확인할 수 있어요.'].map(t=>'<p>'+t+'</p>').join(''));});}
let fishingFloat=null,fishingLine=null,fishShadow=null,catchModel=null,fishingView=null;
function equipRod(){const r=player.userData.rig;if(!r.rod){const g=new THREE.Group();g.position.set(0,-.55,.05);const joints=[];for(let i=0;i<7;i++){const part=cyl(.025,.035,.4,'#ad8052',0,i*.38,0,g,8);joints.push(part);}const reel=orb(.12,.12,.1,'#e6c387',0,.2,.12,g);r.rightArm.add(g);r.rod=g;r.rodParts=joints;}r.rod.visible=true;
 if(!fishingFloat){fishingFloat=new THREE.Group();orb(.12,.16,.12,'#e18a5b',0,0,0,fishingFloat);orb(.13,.07,.13,'#fff3c5',0,.11,0,fishingFloat);scene.add(fishingFloat);const geo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3()]);fishingLine=new THREE.Line(geo,new THREE.LineBasicMaterial({color:'#fff3d4'}));scene.add(fishingLine);fishShadow=orb(.24,.025,.65,'#3c7376',0,-.57,0);catchModel=new THREE.Group();orb(.22,.13,.5,'#79b1b3',0,0,0,catchModel);const tail=cyl(0,.24,.3,'#518b92',0,0,-.5,catchModel,3);tail.rotation.x=Math.PI/2;orb(.04,.04,.04,'#243f40',.16,.04,.3,catchModel);scene.add(catchModel);}
 fishingFloat.visible=true;fishingLine.visible=true;fishShadow.visible=true;catchModel.visible=false;}
function beginFishing(){if(fishState||workTask||!level(s,'fishing')||sea)return false;const p=placementOf('fishing');if(Math.hypot(player.position.x-p.x,player.position.z-p.z)>2.5)return false;standUp();cancelMove();clearKeys();stopJoystick();const len=Math.hypot(p.x,p.z)||21;
 fishingView={yaw,pitch,zoom,focus:focusPoint?.clone()||null};fishState={phase:'cast',left:2,total:2,origin:player.position.clone(),point:new THREE.Vector3(p.x/len*26,-.49,p.z/len*26),awarded:false};player.rotation.y=Math.atan2(fishState.point.x-player.position.x,fishState.point.z-player.position.z);focusPoint=player.position.clone().lerp(fishState.point,.43);yaw=player.rotation.y+1.1;pitch=.48;zoom=12;
 equipRod();document.body.classList.toggle('fishing-view',true);$('#actionProgress').hidden=false;$('#fishResult').hidden=true;$('#fishCancel').hidden=false;$('#fishReel').hidden=true;return true;}
function endFishingView(){if(fishingView){yaw=fishingView.yaw;pitch=fishingView.pitch;zoom=fishingView.zoom;focusPoint=fishingView.focus;fishingView=null;}for(const o of [fishingFloat,fishingLine,fishShadow,catchModel])if(o)o.visible=false;document.body.classList.toggle('fishing-view',false);$('#fishResult').hidden=true;}
function continueFishing(){if(fishState?.phase!=='result')return false;fishState.phase='cast';fishState.left=fishState.total=2;fishState.awarded=false;fishState.caught=null;catchModel.visible=false;fishingFloat.visible=fishingLine.visible=fishShadow.visible=true;$('#fishResult').hidden=true;$('#fishCancel').hidden=false;$('#actionProgress').hidden=false;return true;}
function poseFishing(r){const f=fishState;if(!f)return;const progress=1-Math.max(0,f.left)/f.total;const cast=f.phase==='cast',pull=f.phase==='bite'||f.phase==='reel',result=f.phase==='result';r.body.position.y-=.4;r.leftLeg.rotation.x=r.rightLeg.rotation.x=-1.25;r.leftArm.rotation.x=-.8;r.body.rotation.x=pull?-.12:.06;
 r.rightArm.rotation.x=cast?-.2-Math.sin(progress*Math.PI)*2.4:result?-2.3:pull?-1.2+Math.sin(elapsed*7)*.12:-.8+Math.sin(elapsed*1.4)*.025;
 r.leftArm.rotation.z=pull?Math.sin(elapsed*9)*.18:0;r.rod.rotation.x=2.2;
 r.rodParts.forEach((o,i)=>{const bend=pull?.12*Math.sin(i/6*Math.PI/2):0;o.position.z=-bend*i*.45;o.rotation.x=-bend*2;});
 if(fishingLine){player.updateMatrixWorld(true);const tip=r.rod.localToWorld(new THREE.Vector3(0,2.5,-(pull?.32:0)));const end=result?catchModel.position:fishingFloat.position;const pos=fishingLine.geometry.attributes.position;pos.setXYZ(0,tip.x,tip.y,tip.z);pos.setXYZ(1,end.x,end.y,end.z);pos.needsUpdate=true;fishingLine.geometry.computeBoundingSphere();}}
function makeCaughtObject(caught){if(catchModel){disposeBranch(catchModel);scene.remove(catchModel);}catchModel=new THREE.Group();scene.add(catchModel);const id=caught.id;if(['minnow','seabass','moonfish'].includes(id)){const color=id==='moonfish'?'#d5c6ee':id==='seabass'?'#72a891':'#8ab8ce';orb(.22,.14,.5,color,0,0,0,catchModel);const tail=cyl(0,.23,.3,color,0,0,-.5,catchModel,3);tail.rotation.x=Math.PI/2;orb(.04,.04,.04,'#243f40',.16,.04,.3,catchModel);}else if(id==='seaweed'){for(let i=0;i<3;i++){const leaf=orb(.09,.4,.04,'#589b65',(i-1)*.13,0,0,catchModel);leaf.rotation.z=(i-1)*.3;}}else if(id==='shell'){orb(.32,.12,.26,'#efd3ba',0,0,0,catchModel);}else if(id==='driftwood'){const log=cyl(.12,.15,.7,'#a37d59',0,0,0,catchModel,8);log.rotation.z=1.2;}else{box(.48,.35,.36,id==='chest'?'#bd904b':'#9aaeb1',0,0,0,catchModel);box(.08,.4,.4,id==='chest'?'#e8c77b':'#719a9e',0,0,0,catchModel);}catchModel.visible=false;}
function reelFish(){if(!fishState||fishState.phase!=='bite')return false;fishState.caught=catchChoice(level(s,'fishing'));makeCaughtObject(fishState.caught);fishState.phase='reel';fishState.left=fishState.total=2.2;return true;}
function updateFishing(dt){const f=fishState;if(!f)return;if(sea||dialogue||placement||player.position.distanceTo(f.origin)>.12){cancelWork();return;}if(f.phase==='result'){catchModel.position.copy(f.origin).add(new THREE.Vector3(.3,2.1,0));return;}f.left=Math.max(0,f.left-dt);const progress=1-f.left/f.total;
 if(f.phase==='cast'){const start=f.origin.clone().add(new THREE.Vector3(0,1.5,0));fishingFloat.position.copy(start.lerp(f.point,progress));fishingFloat.position.y+=Math.sin(progress*Math.PI)*2;fishShadow.position.copy(f.point).add(new THREE.Vector3(1.5,-.08,1));}
 else if(f.phase==='reel'){fishingFloat.position.copy(f.point).lerp(f.origin.clone().add(new THREE.Vector3(0,2,0)),progress);fishingFloat.position.y+=Math.sin(progress*Math.PI)*1.5;catchModel.visible=true;catchModel.position.copy(fishingFloat.position);catchModel.rotation.z=Math.sin(elapsed*12)*.25;fishShadow.visible=false;}
 else{fishingFloat.position.copy(f.point);fishingFloat.position.y+=Math.sin(elapsed*(f.phase==='bite'?12:2))*(f.phase==='bite'?.13:.035);if(f.phase==='bite')fishingFloat.position.y-=.12;fishShadow.position.lerp(new THREE.Vector3(f.point.x,-.56,f.point.z),Math.min(1,dt*.6));}
 paintWork(f.phase,f.left,f.total,f.point);if(f.left>0)return;
 if(f.phase==='cast'){f.phase='wait';f.left=f.total=4+Math.random()*2;ripple(f.point,'water');return;}
 if(f.phase==='wait'){f.phase='bite';f.left=f.total=2.5;ripple(f.point,'water');beep(620);return;}
 if(f.phase==='bite'){reelFish();burst(f.point,'water',10);return;}
 if(f.awarded)return;f.awarded=true;const caught=f.caught,amount=1+skillBonus('fishing');f.phase='result';s.items[caught.id]+=amount;s.catchCount++;awardSkill('fishing');if(caught.id==='scrap')s.recycled++;discover(caught.id);fishingFloat.visible=false;$('#actionProgress').hidden=true;$('#fishResultText').textContent=caught.icon+' '+caught.name+' ×'+amount;$('#fishResult').hidden=false;$('#fishCancel').hidden=true;save();render();}
$('#fishContinue').onclick=continueFishing;$('#fishFinish').onclick=()=>cancelMove();

function drawHaven(){const lv=havenLevel(s),p=placementOf('haven'),g=new THREE.Group();g.position.set(p.x,0,p.z);g.rotation.y=p.rotation||0;lifeGroup.add(g);havenMesh=g;lifeFlames=[];
// The fire remains a social space even after the shelter grows behind it.
for(let i=0;i<9;i++)orb(.3,.18,.25,mats.rock,Math.sin(i*.7)*.85,.51,Math.cos(i*.7)*.85,g);
for(const a of [-.6,.6]){const log=cyl(.13,.13,1.3,mats.trunk,0,.6,0,g,12);log.rotation.z=Math.PI/2;log.rotation.y=a;}
if(lv){for(let i=0;i<4;i++){const f=orb(.15,.35,.15,i%2?'#f4d77e':'#e8a658',Math.sin(i*2)*.2,.9,Math.cos(i*2)*.2,g);f.material.emissive=new THREE.Color('#d88d39');f.material.emissiveIntensity=.9;lifeFlames.push(f);}const l=new THREE.PointLight('#ffc875',1.4,7,2);l.position.set(0,1.3,0);g.add(l);}
if(lv===2){orb(1.8,1.5,1.2,'#969887',0,1.35,-2.1,g);orb(.8,1,.15,'#3c4a43',0,1,-.95,g);}
if(lv===3){box(2.4,1.3,1.7,'#bba98b',0,1.1,-2,g);const roof=box(2.9,.16,2.1,'#8d9d81',0,1.9,-2,g);roof.rotation.z=.12;box(.5,.85,.1,mats.trunk,0,.9,-1.1,g);}
if(lv>=4){const size=1+(lv-4)*.12;box(2.7*size,1.7+(lv-4)*.25,2.2,'#eee0b6',0,1.35+(lv-4)*.12,-2.2,g);const roof=box(3.3*size,.55,2.8,lv===4?'#c2ae6d':lv<7?'#bb825c':'#799a92',0,2.45+(lv-4)*.26,-2.2,g);box(.55,1.1,.1,mats.trunk,0,1,-1.05,g);for(const x of [-.85,.85])box(.55,.6,.08,mats.blue,x,1.6,-1.05,g);if(lv>=7){box(4.2,.18,1.1,mats.wood,0,2.5,-.8,g);for(const x of [-1.7,1.7])box(.12,1.8,.12,mats.white,x,1.45,-.5,g);}if(lv===8){box(2.2,1.4,2,'#e5dfd0',0,3.3,-2.2,g);box(2.6,.3,2.4,'#688e88',0,4.1,-2.2,g);}}
if(lv)buildingGroups.set('haven',g);
}
function makeCapy(){const g=new THREE.Group();let pos={x:3,z:-1.2};const clear=p=>Math.hypot(p.x,p.z)<21&&!footprintEntries().some(f=>Math.hypot(p.x-f.x,p.z-f.z)<f.radius+1)&&Math.hypot(p.x-board.position.x,p.z-board.position.z)>2;if(!clear(pos)){const c=placementOf('haven');for(let a=0;a<6.3;a+=.4){const p={x:c.x+Math.sin(a)*4.8,z:c.z+Math.cos(a)*4.8};if(clear(p)){pos=p;break;}}}g.position.set(pos.x,.45,pos.z);lifeGroup.add(g);orb(.68,.57,1,'#a98b63',0,.65,0,g);orb(.55,.48,.6,'#b89b72',0,1,.65,g);box(.65,.35,.58,'#b89b72',0,.85,1,g);for(const x of [-.35,.35]){orb(.14,.16,.12,'#947653',x,1.38,.6,g);orb(.055,.06,.04,'#35483a',x*.7,1.05,1.2,g);for(const z of [-.5,.6])box(.21,.25,.25,'#8f7453',x,.25,z,g);}box(.32,.4,.17,'#718d70',.65,.7,0,g);box(.8,.4,.6,mats.wood,1.3,.5,.5,g);orb(.19,.17,.18,'#e8ab60',1.3,.8,.5,g);g.rotation.y=-.3;capybara=g;discover('capy');}
function drawFishingDock(){if(!level(s,'fishing'))return;const p=placementOf('fishing'),g=new THREE.Group();g.position.set(p.x,0,p.z);g.rotation.y=Math.atan2(p.x,p.z);lifeGroup.add(g);box(2.2,.25,4,'#b48b5b',0,.38,1,g);for(let i=0;i<7;i++)box(2.1,.025,.03,'#775e43',0,.52,-.6+i*.55,g);for(const x of [-.9,.9])box(.14,1.2,.14,mats.trunk,x,.5,2.6,g);if(level(s,'fishing')>=2){box(2.5,.15,2.3,'#86a293',0,2.5,0,g);for(const x of [-1,1])box(.1,2,.1,mats.wood,x,1.4,0,g);}if(level(s,'fishing')===3)box(.8,.6,.8,'#ccb285',.6,.8,1,g);buildingGroups.set('fishing',g);}
function drawLifeDecor(d){const def=DECOR.find(k=>k.id===d.kind),g=new THREE.Group();g.position.set(d.x,.45,d.z);g.rotation.y=d.rotation||0;lifeGroup.add(g);if(d.kind==='bench'){box(1.8,.18,.65,mats.wood,0,.45,0,g);box(1.8,.65,.12,mats.wood,0,.85,-.3,g);for(const x of [-.7,.7])box(.12,.5,.5,mats.trunk,x,.2,0,g);}if(d.kind==='flowers')for(let i=0;i<7;i++){const x=Math.sin(i*2)*.4,z=Math.cos(i*2)*.4;cyl(.025,.025,.35,mats.leaf,x,.2,z,g,6);orb(.13,.07,.13,i%2?'#f1c19d':'#f6df89',x,.4,z,g);}if(d.kind==='path')cyl(.62,.65,.06,'#c8c4ad',0,.04,0,g,8);if(d.kind==='fence'){box(1.6,.12,.13,mats.wood,0,.5,0,g);box(1.6,.12,.13,mats.wood,0,.85,0,g);for(const x of [-.7,.7])box(.15,1,.15,mats.trunk,x,.5,0,g);}if(d.kind==='lamp'){cyl(.06,.08,1.7,mats.trunk,0,.85,0,g,10);const bulb=orb(.28,.32,.28,'#f4dea3',0,1.7,0,g);bulb.material.emissive=new THREE.Color('#ffd78c');bulb.material.emissiveIntensity=1;nightWindows.push(bulb.material);const light=new THREE.PointLight('#ffd78c',0,4,2);light.position.y=1.7;g.add(light);nightWindows.push(light);}lifeDecorObjects.set(d.id,g);}
function makeSeaLife(){seaLife=[];for(let i=0;i<12;i++){const g=new THREE.Group();const shark=i===0,trash=i>8;const radius=shark?35:27+i*.8;const angle=i*.62;g.userData={radius,angle,speed:shark?.09:trash?.015:.13};if(trash){box(.3,.16,.25,'#a2b7a1',0,0,0,g);box(.12,.12,.12,'#d7c59a',.16,.08,0,g);}else{orb(shark?.7:.15,shark?.3:.08,shark?1.5:.4,shark?'#71918e':'#568f97',0,0,0,g);const fin=cyl(0,shark?.4:.12,shark?.65:.22,shark?'#648382':'#568f97',0,shark?.35:.02,.2,g,3);if(!shark)fin.rotation.x=Math.PI/2;}g.position.set(Math.sin(angle)*radius,trash?-.52:-.47,Math.cos(angle)*radius);g.rotation.y=angle+Math.PI/2;lifeGroup.add(g);seaLife.push(g);}}
function drawBeachPickups(){beachObjects.clear();for(const p of s.beachPickups.filter(p=>!p.collected)){const g=new THREE.Group();g.position.set(p.x,.48,p.z);if(p.kind==='letter'){cyl(.14,.14,.45,'#a1c7bb',0,.2,0,g,12);box(.12,.2,.06,mats.white,0,.2,.14,g);}else if(p.kind==='shell'){orb(.23,.1,.2,'#edd5b9',0,.1,0,g);}else{const log=cyl(.12,.13,.75,mats.trunk,0,.15,0,g,10);log.rotation.z=Math.PI/2;}lifeGroup.add(g);beachObjects.set(p.id,g);}}
function rebuildLifeWorld(){const gone=new Set();lifeGroup.traverse(o=>{if(o.isLight)gone.add(o);if(o.isMesh)gone.add(o.material);});nightWindows=nightWindows.filter(o=>!gone.has(o));disposeBranch(lifeGroup);lifeGroup.clear();lifeDecorObjects.clear();drawHaven();makeCapy();drawFishingDock();for(const d of s.decorPlaced)drawLifeDecor(d);drawBeachPickups();makeSeaLife();syncResources();}
function refreshBeach(){const day=Math.floor(s.time/1200);if(s.beachDay===day)return;s.beachDay=day;s.beachPickups=s.beachPickups.filter(p=>!p.collected).slice(-6);for(let i=0;i<3;i++){const angle=1.6+i*.42+(day%3)*.12;s.beachPickups.push({id:'beach-'+day+'-'+i,kind:['letter','shell','wood'][i],x:Math.sin(angle)*22,z:Math.cos(angle)*22,collected:false});}rebuildLifeWorld();save();}
function collectBeach(p){if(p.collected)return;beginWork('beach',2,new THREE.Vector3(p.x,0,p.z),()=>{p.collected=true;if(p.kind==='letter'){s.lettersFound++;discover('letter');toast('바다 건너온 편지병을 찾았어요! 게시판의 화단 부탁을 확인해요.');}else{const k=p.kind==='wood'?'wood':'shell';discover('beach-'+p.kind);gainItems({[k]:1});}rebuildLifeWorld();});}
// Rest is a temporary pose; progress and world time continue while the player relaxes.
let restState=null;
function beginRest(bench=null){if(sea||placement)return false;const center=bench||placementOf('haven');if(!bench&&!havenLevel(s))return false;if(Math.hypot(player.position.x-center.x,player.position.z-center.z)>(bench?2.2:3))return false;cancelMove();clearKeys();stopJoystick();const rig=player.userData.rig;rig.action=0;rig.actionTarget=null;if(rig.tools)Object.values(rig.tools).forEach(tool=>tool.visible=false);if(rig.rod)rig.rod.visible=false;
if(bench){player.position.set(bench.x,.45,bench.z);player.rotation.y=bench.rotation||0;}else player.rotation.y=Math.atan2(center.x-player.position.x,center.z-player.position.z);
restState={benchId:bench?.id||null,x:player.position.x,z:player.position.z};rig.restDepth=bench?.1:.48;$('#restControl').hidden=false;panelOpen=false;render();return true;}
function standUp(){if(!restState)return;restState=null;$('#restControl').hidden=true;}
function updateRest(){if(!restState)return;const r=restState;if(sea||Math.hypot(player.position.x-r.x,player.position.z-r.z)>.15){standUp();return;}if(r.benchId){const d=s.decorPlaced.find(d=>d.id===r.benchId);if(!d||Math.hypot(d.x-r.x,d.z-r.z)>.15)standUp();}}
function applyRestPose(g,r,dt){if(g!==player)return;r.restBlend=THREE.MathUtils.damp(r.restBlend||0,restState?1:0,7,dt);const b=r.restBlend;if(b<.001){r.restBlend=0;return;}r.body.position.y-=(r.restDepth??.48)*b;r.leftLeg.rotation.x=THREE.MathUtils.lerp(r.leftLeg.rotation.x,-1.4,b);r.rightLeg.rotation.x=THREE.MathUtils.lerp(r.rightLeg.rotation.x,-1.4,b);r.leftArm.rotation.x=THREE.MathUtils.lerp(r.leftArm.rotation.x,-.5+Math.sin(elapsed*1.5)*.025,b);r.rightArm.rotation.x=THREE.MathUtils.lerp(r.rightArm.rotation.x,-.5-Math.sin(elapsed*1.5)*.025,b);r.body.rotation.x=THREE.MathUtils.lerp(r.body.rotation.x,.08,b);r.body.rotation.z*=1-b;}
function eveningTalk(){const day=Math.floor(s.time/1200);if(!havenLevel(s)){toast('먼저 모닥불을 마련해 주세요.');return;}if(skyPhase().hour<18||skyPhase().hour>=22){showDialogue('모닥불 곁에서',['저녁이 되면 이웃들이 이곳에 모여 쉬어요. 원할 때 잠깐 함께 앉아 보세요.']);beginRest();return;}const fresh=s.eveningDay!==day;if(fresh){s.eveningDay=day;gainItems({food:1});save();}showDialogue('우리의 저녁 모임',['오늘도 조금씩 달라진 섬에서 하루를 보냈네요.','불빛과 파도 소리를 들으며 잠깐 쉬어 가요.'+(fresh?' 이웃이 식량 하나를 나누어 줬어요.':'')]);beginRest();}
function lifeTargets(){return [{kind:'capy',ref:capybara},...(havenLevel(s)?[]:[{kind:'camp',ref:havenMesh}]),...s.decorPlaced.map(ref=>({kind:'decor',ref})),...s.beachPickups.filter(p=>!p.collected).map(ref=>({kind:'beach',ref}))];}
function lifeWorldObject(t){return t.kind==='capy'?capybara:t.kind==='camp'?havenMesh:t.kind==='decor'?lifeDecorObjects.get(t.ref.id):t.kind==='beach'&&!t.ref.collected?beachObjects.get(t.ref.id):null;}
function lifeActions(t){if(t.kind==='capy')return [{key:'capy',label:'🦫 카피와 이야기',range:2}];if(t.kind==='camp')return [{key:'haven',label:'🔥 모닥불 준비',range:0}];if(t.kind==='beach')return [{key:'beach',label:'🐚 해변의 선물 줍기',range:1.8}];if(t.kind==='decor')return [...(t.ref.kind==='bench'?[{key:'restBench',label:'🪑 앉아서 쉬기',range:1.7}]:[]),{key:'decorMove',label:'↔️ 위치 바꾸기',range:0},{key:'decorReturn',label:'📦 돌려받기',range:0}];if(t.kind==='building'&&t.id==='haven')return [{key:'haven',label:'🔥 보금자리 발전',range:0},{key:'evening',label:'🌙 모닥불에서 쉬기',range:2.5},{key:'details',label:'ⓘ 성장 기록',range:0}];if(t.kind==='building'&&t.id==='fishing')return [{key:'fish',label:'🎣 낚시하기',range:2.3},{key:'upgrade',label:'⬆️ 낚시터 업그레이드',range:0,disabled:level(s,'fishing')>=3||!upgradeAllowed(defs.find(d=>d.id==='fishing'),level(s,'fishing'))||!afford(upgradeCost(s,defs.find(d=>d.id==='fishing')))}];return null;}
function performLifeAction(t,key){if(key==='capy')capyTalk();else if(key==='haven'||(key==='details'&&t.id==='haven'))showHaven();else if(key==='evening')eveningTalk();else if(key==='restBench')beginRest(t.ref);else if(key==='fish')beginFishing();else if(key==='beach')collectBeach(t.ref);else if(key==='decorMove')startPlacement('decor:'+t.ref.kind,'decorMove',t.ref.id);else if(key==='decorReturn'){const d=t.ref;s.decorPlaced=s.decorPlaced.filter(k=>k.id!==d.id);s.decorTokens??={};s.decorTokens[d.kind]=(s.decorTokens[d.kind]||0)+1;rebuildLifeWorld();save();toast('장식을 돌려받았어요. 꾸미기에서 다시 놓을 수 있어요.');}else return false;return true;}
let actionMenuUntil=0;
function updateActionMenuVisibility(){const busy=!!workTask||!!fishState||!!restState||!!placement||elapsed<actionMenuUntil;document.body.classList.toggle('performing-action',busy);}
function updateLife(dt){updateActionMenuVisibility();updateWork(dt);updateRest();updateNodes(dt);for(const [i,f]of lifeFlames.entries()){f.scale.y=.28+Math.sin(elapsed*4+i)*.07;f.position.y=.9+Math.sin(elapsed*3+i)*.035;}if(capybara){const target=Math.atan2(player.position.x-capybara.position.x,player.position.z-capybara.position.z);if(capybara.position.distanceTo(player.position)<6)capybara.rotation.y=THREE.MathUtils.damp(capybara.rotation.y,target,1.2,dt);capybara.position.y=.45+Math.sin(elapsed*1.3)*.015;}for(const g of seaLife){g.userData.angle+=dt*g.userData.speed;g.position.x=Math.sin(g.userData.angle)*g.userData.radius;g.position.z=Math.cos(g.userData.angle)*g.userData.radius;g.rotation.y=g.userData.angle+Math.PI/2;}lifeTick+=dt;if(lifeTick>2){lifeTick=0;refreshBeach();for(const a of animals){if(a.position.distanceTo(player.position)<7)discover('animal-'+(a.userData.kind==='bird'?'bird':a.userData.kind==='deer'?'deer':'rabbit'));}paintGoal();}}
function residentDestination(r,i){const p=PERSONALITIES[i%4],evening=skyPhase().hour>=18&&skyPhase().hour<22&&havenLevel(s);if(evening){const c=placementOf('haven');return {x:c.x+Math.sin(i*2)*2,z:c.z+Math.cos(i*2)*2,rest:true};}if(!r.jobKey){if(p.like==='fishing'&&level(s,'fishing'))return {...placementOf('fishing'),rest:false};if(p.like==='rain'&&s.weather==='rain'){const c=level(s,'pond')?placementOf('pond'):placementOf('haven');return {x:c.x+2,z:c.z+1,rest:false};}const d=s.decorPlaced.find(d=>d.kind===(p.like==='flowers'?'flowers':'bench'))||s.decorPlaced.find(d=>d.kind==='bench');if(d)return {x:d.x,z:d.z,rest:d.kind==='bench'};if(p.like==='fishing'&&level(s,'fishing'))return {...placementOf('fishing'),rest:false};}return null;}

const menuScroll={};
function menuTiles(){const tiles=[];const add=(key,name,action,locked=false)=>tiles.push(`<button class="menu-tile" data-menu-action="${action}" aria-label="${name}${locked?' · 잠김':''}"><span class="tile-picture">${svgIcon(key)}${locked?'<i>🔒</i>':''}</span><span class="tile-name">${name}</span></button>`);
if(tab==='nature'){add('decor','섬 꾸미기','decor');add('journal','발견 도감','journal');add('sapling','열매나무','plant');}
if(tab==='life'){add('haven',havenLevel(s)?HAVENS[havenLevel(s)-1].name:'모닥불','haven');if(level(s,'house'))add('extra','주택 추가','extra');for(const [i,h]of s.homes.entries())add('home','주택 '+(i+1),'home:'+h.id);}
if(tab==='production'){add('trade','카피의 상점','trade');add('bag','채집 가방','bag');add('journal','숙련도','skills');}
if(['nature','life','production','sea'].includes(tab))for(const d of defs.filter(d=>d.category===tab&&d.id!=='haven'&&(level(s,d.id)||(GATES[d.id]||0)<=havenLevel(s)+1)))add(d.id,d.name,'building:'+d.id,!level(s,d.id)&&requirements(s,d).length>0);
if(tab==='people'){if(s.visitor)add('visitor',s.visitor.name,'visitor');for(const r of s.residents)add('resident',r.name,'resident:'+r.id);if(!s.visitor&&!s.residents.length)add('house','새 이웃 맞이','residentsIntro');}
if(tab==='sea'){add('sailing',sea?'귀항하기':'출항하기','sailing');for(const [i,a]of islands.entries())add('island',s.discovered.includes(i)?a.name:'미지의 섬','island:'+i);}
if(tab==='events'){for(const e of LIFE_EVENTS)add('event',e.name,'lifeEvent:'+e.id);for(const e of EVENT_DEFS)add('event',e.title,'baseEvent:'+e.id);add('beach','해변 소식','beach');add('journal','발견 도감','journal');}
if(tab==='settings'){add('help','섬 관리','manage');add('island','다음 지역','regions');add('resident','찾기','find');add('character','주인공 꾸미기','character');add('audio','배경음악','audio');add('journal','숙련도','skills');add('help','게임 안내','help');}
return `<div class="tile-slider" data-category="${tab}" aria-label="${categories[tab][1]} 목록">${tiles.join('')}</div><button class="slider-next" id="sliderNext" aria-label="다음 목록">›</button>`;}
function selectMenuTile(value){panelOpen=false;render();const [kind,id]=value.split(':');if(kind==='manage'){showManagement();return;}if(kind==='regions'){showRegions();return;}if(kind==='find'){showFinder();return;}if(kind==='building')showDetails('building',id);else if(kind==='home')showDetails('home',id);else if(kind==='plant'||kind==='extra'||kind==='residentsIntro')showDetails(kind);else if(kind==='resident')talkTo(npcs.find(n=>n.userData.resident.id===Number(id)));else if(kind==='visitor')talkTo(visitorMesh);else if(kind==='sailing')showDetails('sailing');else if(kind==='island')showDetails('island',id);else if(kind==='baseEvent')showDetails('event',id);else if(kind==='lifeEvent')showLifeEvent(id);else if(kind==='haven')showHaven();else if(kind==='trade')showTrade();else if(kind==='bag')showBag();else if(kind==='journal')showJournal();else if(kind==='decor')showDecor();else if(kind==='character')openAvatarEditor();else if(kind==='audio')showAudioSettings();else if(kind==='skills')showSkills();else if(kind==='beach')lifeDialog('💌 해변 소식','<p>파도가 편지병과 조개, 유목을 두고 갔어요. 해변에서 작은 선물을 찾아보세요.</p>');else if(kind==='help')$('#helpDialog').showModal();}
function bindMenuTiles(pc){pc.querySelectorAll('[data-menu-action]').forEach(b=>b.onclick=()=>selectMenuTile(b.dataset.menuAction));const next=document.querySelector('#sliderNext'),slider=document.querySelector('#panelContent .tile-slider');if(next&&slider)next.onclick=()=>slider.scrollBy({left:Math.max(180,slider.clientWidth*.7),behavior:'smooth'});}
function showAudioSettings(){lifeDialog('♫ 섬의 소리',`<p>바람과 파도에 어울리는 음악을 들어요.</p><label>음량 <input id="lifeVolume" type="range" min="0" max="100" value="${Math.round(s.volume*100)}"></label>`,[{label:s.audioOn?'음악 끄기':'음악 켜기',action:()=>{toggleMusic();showAudioSettings();}}]);$('#lifeVolume').oninput=e=>{s.volume=+e.target.value/100;setVolume();};}

let nodesReady=false;
function skillStats(kind){let xp=Math.max(0,Math.floor(s.skills?.[kind]?.xp||0)),level=1,spent=0;while(level<10&&xp>=spent+level*10){spent+=level*10;level++;}return {level,xp,current:xp-spent,next:level*10,chance:Math.min(.2,(level-1)*.025)};}
function skillBonus(kind,random=Math.random()){return random<skillStats(kind).chance?1:0;}
let skillFeedbackLeft=0;
function awardSkill(kind){s.skills??={};s.skills[kind]??={xp:0};const before=skillStats(kind).level;s.skills[kind].xp++;const stat=skillStats(kind);$('#skillFeedback').textContent=`${kind==='fishing'?'낚시':'채집'} Lv.${stat.level} · ${stat.level>before?'레벨 업!':'경험치 +1'}`;$('#skillFeedback').hidden=true;skillFeedbackLeft=0;}
function showSkills(){lifeDialog('🌱 섬 생활 숙련도',`<p>활동을 마칠 때 경험치가 올라요. 느긋한 작업 속도는 그대로, 가끔 재료를 하나 더 얻어요.</p>${['gather','fishing'].map(k=>{const r=skillStats(k);return `<article class="skill-card"><b>${k==='gather'?'채집':'낚시'} Lv.${r.level}</b><small>경험치 ${r.level>=10?'최고 레벨':r.current+' / '+r.next} · 추가 획득 확률 ${Math.round(r.chance*1000)/10}%</small><div class="action-track"><i style="width:${r.level>=10?100:Math.min(100,r.current/r.next*100)}%"></i></div></article>`;}).join('')}`);}
function nodeCapacity(kind){return kind==='wood'?6+Math.floor(Math.random()*5):kind==='stone'?4+Math.floor(Math.random()*4):3+Math.floor(Math.random()*3);}
function snapshotNodes(){if(!nodesReady)return;s.resourceNodes=resources.map(r=>({id:r.id,type:r.type,x:r.x,z:r.z,max:r.max,remaining:r.remaining}));}
function initializeNodes(){for(const k of ['gather','fishing']){s.skills??={};s.skills[k]={xp:Math.max(0,Math.floor(Number(s.skills[k]?.xp)||0))};}s.resourceWaiting=Array.isArray(s.resourceWaiting)?s.resourceWaiting.filter(r=>['wood','stone','food'].includes(r.type)).slice(0,50):[];s.nodeSerial=Math.max(Number(s.nodeSerial)||0,50);
const saved=Array.isArray(s.resourceNodes)?s.resourceNodes.filter(r=>['wood','stone','food'].includes(r.type)&&Number.isFinite(r.x)&&Number.isFinite(r.z)&&Math.hypot(r.x,r.z)<23&&r.remaining>0).slice(0,60):null;
if(saved){for(const r of resources){r.g.removeFromParent();disposeBranch(r.g);}resources.length=0;for(const data of saved){const maker=data.type==='wood'?tree:data.type==='stone'?rock:bush;maker(data.x,data.z);const r=resources[resources.length-1];r.id=data.id||'node-'+s.nodeSerial++;r.max=Math.max(1,Math.min(20,Math.floor(data.max)||1));r.remaining=Math.min(r.max,Math.max(1,Math.floor(data.remaining)));}}
else for(const r of resources){r.id='node-'+s.nodeSerial++;r.max=nodeCapacity(r.type);r.remaining=r.max;}
nodesReady=true;snapshotNodes();}
function removeSpentNode(r){if(!resources.includes(r)||r.remaining>0)return;resources.splice(resources.indexOf(r),1);r.g.visible=false;r.g.removeFromParent();disposeBranch(r.g);s.resourceWaiting.push({type:r.type,at:s.time+14+Math.random()*12,oldX:r.x,oldZ:r.z});}
function nodeLocation(wait){for(let attempt=0;attempt<100;attempt++){const region=regions.filter(regionOpen)[Math.floor(Math.random()*regions.filter(regionOpen).length)],radius=Math.sqrt(Math.random())*(region.r-2),angle=Math.random()*Math.PI*2,x=region.x+Math.sin(angle)*radius,z=region.z+Math.cos(angle)*radius;if(Math.hypot(x-(wait.oldX||0),z-(wait.oldZ||0))<3)continue;if(!validPlacement('sapling',x,z)||s.decorPlaced.some(d=>Math.hypot(d.x-x,d.z-z)<2))continue;if(resources.some(r=>Math.hypot(r.x-x,r.z-z)<2.3))continue;if(Math.hypot(x-player.position.x,z-player.position.z)<3.5)continue;return {x,z};}return null;}
function updateNodes(dt){if(skillFeedbackLeft>0){skillFeedbackLeft-=dt;if(skillFeedbackLeft<=0)$('#skillFeedback').hidden=true;}let changed=false;for(let i=s.resourceWaiting.length-1;i>=0;i--){const wait=s.resourceWaiting[i];if(s.time<wait.at)continue;const p=nodeLocation(wait);if(!p){wait.at=s.time+5;continue;}const maker=wait.type==='wood'?tree:wait.type==='stone'?rock:bush;maker(p.x,p.z);const r=resources[resources.length-1];r.id='node-'+s.nodeSerial++;r.max=nodeCapacity(r.type);r.remaining=r.max;s.resourceWaiting.splice(i,1);changed=true;}if(changed){syncResources();save();}}

const animalWander=new WeakMap();
function wanderAnimal(a,i,dt){const bird=a.userData.kind==='bird',homeId=bird?'orchard':a.userData.kind==='deer'?'pond':'habitat';let c=placementOf(homeId);if(a.userData.origin)c={x:a.userData.origin[0],z:a.userData.origin[1]};if(havenLevel(s)&&skyPhase().hour>=18&&skyPhase().hour<22)c=placementOf('haven');let w=animalWander.get(a);if(!w){w={x:c.x,z:c.z,pause:Math.random()*3,speed:bird?.65:.3+Math.random()*.25};animalWander.set(a,w);a.position.x=c.x+Math.sin(i)*1.7;a.position.z=c.z+Math.cos(i)*1.7;}const safe=(x,z)=>insideLand(x,z,1)&&!footprintEntries().some(f=>f.id!==homeId&&f.id!=='haven'&&Math.hypot(x-f.x,z-f.z)<f.radius+.2);w.pause-=dt;const dist=Math.hypot(w.x-a.position.x,w.z-a.position.z);if(w.pause<=0&&dist<.12){w.pause=1+Math.random()*4;for(let n=0;n<12;n++){const angle=Math.random()*6.28,r=1.4+Math.random()*2.5,x=c.x+Math.sin(angle)*r,z=c.z+Math.cos(angle)*r;if(safe(x,z)){w.x=x;w.z=z;break;}}}let moving=false;if(w.pause<=0&&dist>.1){const step=Math.min(dist,w.speed*dt),dx=(w.x-a.position.x)/dist,dz=(w.z-a.position.z)/dist;const x=a.position.x+dx*step,z=a.position.z+dz*step;if(safe(x,z)){a.position.x=x;a.position.z=z;moving=true;const angle=Math.atan2(dx,dz),delta=Math.atan2(Math.sin(angle-a.rotation.y),Math.cos(angle-a.rotation.y));a.rotation.y+=delta*Math.min(1,dt*2);}else{w.x=a.position.x;w.z=a.position.z;w.pause=.5;}}a.position.y=(bird?1.1:.45)+(moving?Math.abs(Math.sin(elapsed*5+i))*(bird?.08:.035):Math.sin(elapsed*1.5+i)*.008);}
function polishIsland(){for(let i=0;i<70;i++){const angle=i*2.399,r=8+((i*17)%130)/10,x=Math.sin(angle)*r,z=Math.cos(angle)*r;if(Math.hypot(x,z)>21.5)continue;const g=new THREE.Group();g.position.set(x,.43,z);scene.add(g);for(let j=0;j<3;j++){const grass=orb(.035,.15,.035,'#9eaf69',j*.08,.12,0,g);grass.rotation.z=(j-1)*.3;}if(i%5===0){orb(.09,.055,.09,'#ebcf8f',0,.24,0,g);orb(.06,.04,.06,'#d9a58d',.16,.2,0,g);}}for(let i=0;i<75;i++){const angle=i/75*Math.PI*2,r=25.1+Math.sin(i*.8)*.25;const foam=orb(.6,.025,.13,'#d0e5cf',Math.sin(angle)*r,-.49,Math.cos(angle)*r);foam.rotation.y=angle;foam.castShadow=false;}}
polishIsland();
