function paintHud(){hudFolded.nav=false;document.body.classList.toggle('folded-nav',false);hudFolded.resources=false;document.body.classList.toggle('folded-resources',false);for(const key of ['info','quest','nav']){const folded=!!hudFolded[key];document.body.classList.toggle('folded-'+key,folded);const button=document.querySelector('[data-hud-fold="'+key+'"]');if(button){const name={resources:'자원',info:'섬 정보',quest:'목표',nav:'메뉴',location:'위치'}[key];const left=key==='info';button.innerHTML='<span class="fold-arrow">'+(key==='nav'?(folded?'⌃':'⌄'):(folded?(left?'›':'‹'):(left?'‹':'›')))+'</span><span class="fold-name">'+name+'</span>';button.setAttribute('aria-expanded',String(!folded));button.setAttribute('aria-label',name+(folded?' 펼치기':' 접기'));}}}
function toggleHud(key){if(key==='resources'||key==='nav')return;hudFolded[key]=!hudFolded[key];if(key==='nav'&&hudFolded[key]){panelOpen=false;render();}paintHud();try{localStorage.setItem(HUD_KEY,JSON.stringify(hudFolded));}catch{}}
