function landscapeMetrics(width,height,coarse=false){const mobile=coarse||Math.min(width,height)<=600;return {mobile,rotated:mobile&&height>width,width:mobile?Math.max(width,height):width,height:mobile?Math.min(width,height):height};}
function gamePointer(e){const vv=typeof window!=='undefined'?window.visualViewport:null,x=e.clientX-(vv?.offsetLeft||0),y=e.clientY-(vv?.offsetTop||0);return {button:e.button,pointerType:e.pointerType,pointerId:e.pointerId,clientX:portraitGame?y:x,clientY:portraitGame?viewHeight-x:y};}
function migrateLifeLayout(){if(level(s,'haven')&&!s.placements.haven){for(let radius=0;radius<19;radius+=2)for(let a=0;a<6.3;a+=.45){const x=Math.sin(a)*radius,z=Math.cos(a)*radius;if(validPlacement('haven',x,z,'haven')&&Math.hypot(x-3,z+1.2)>4){s.placements.haven={x,z,rotation:0};return;}}}}
let landscapeZoomApplied=false;
function syncGameLayout(){const vv=typeof window!=='undefined'?window.visualViewport:null;const width=vv?.width||innerWidth,height=vv?.height||innerHeight;const naming=$('#welcome').open;const m=landscapeMetrics(width,height,typeof matchMedia==='function'&&matchMedia('(pointer:coarse)').matches);if(naming){m.width=width;m.height=height;m.rotated=false;}const changed=viewWidth!==m.width||viewHeight!==m.height||portraitGame!==m.rotated;viewWidth=m.width;viewHeight=m.height;portraitGame=m.rotated;mobileGame=m.mobile;document.body.classList.toggle('mobile-landscape',mobileGame);document.body.classList.toggle('portrait-game',portraitGame);const shell=$('#gameShell');shell.style.width=viewWidth+'px';shell.style.height=viewHeight+'px';shell.style.setProperty('--game-height',viewHeight+'px');shell.style.left=((vv?.offsetLeft||0)+(portraitGame?width:0))+'px';shell.style.top=(vv?.offsetTop||0)+'px';shell.style.transform=portraitGame?'rotate(90deg)':'none';camera.aspect=viewWidth/viewHeight;camera.updateProjectionMatrix();renderer.setSize(viewWidth,viewHeight);if(changed){resetGesture();clearKeys();cancelMove();}if(mobileGame&&!landscapeZoomApplied){zoom=18;landscapeZoomApplied=true;}setInputMode(mobileGame||touchInput);}

let rewardCue=null;
function showReward(items){if(!rewardCue)rewardCue={items:{},left:1.6};for(const [key,value] of Object.entries(items))rewardCue.items[key]=(rewardCue.items[key]||0)+value;rewardCue.left=1.6;$('#rewardPop').textContent=Object.entries(rewardCue.items).map(([k,v])=>(icons[k]||'✦')+' +'+v).join('  ');$('#rewardPop').hidden=false;updateReward(0);}
function updateReward(dt){if(!rewardCue)return;rewardCue.left-=dt;if(rewardCue.left<=0){rewardCue=null;$('#rewardPop').hidden=true;return;}const p=(sea?boat:player).position.clone();p.y+=2.8;p.project(camera);const node=$('#rewardPop');node.style.left=THREE.MathUtils.clamp((p.x+1)*viewWidth/2,85,viewWidth-85)+'px';node.style.top=THREE.MathUtils.clamp((1-p.y)*viewHeight/2-(1.6-rewardCue.left)*18,54,viewHeight-50)+'px';node.style.opacity=Math.min(1,rewardCue.left*3);}
$('#standUp').onclick=()=>{if(dialogue)closeDialogue();standUp();renderer.domElement.focus({preventScroll:true});};$('#fishReel').onclick=reelFish;$('#fishCancel').onclick=cancelWork;addEventListener('resize',syncGameLayout);syncGameLayout();migrateLifeLayout();initializeNodes();

let focusPoint=null;
function walkable(x,z){return insideLand(x,z,.2)&&!footprintEntries().some(p=>!['fishing','dock','haven'].includes(p.id)&&Math.hypot(x-p.x,z-p.z)<p.radius*.72);}
function landPath(from,to){if(!insideLand(to.x,to.z,.15))return null;const clear=(a,b)=>{const n=Math.ceil(Math.hypot(b.x-a.x,b.z-a.z)/.5);for(let i=1;i<=n;i++)if(!walkable(a.x+(b.x-a.x)*i/n,a.z+(b.z-a.z)*i/n))return false;return true;};if(clear(from,to))return [new THREE.Vector3(to.x,.45,to.z)];
 const step=1.5,start={x:Math.round(from.x/step),z:Math.round(from.z/step)},goal={x:Math.round(to.x/step),z:Math.round(to.z/step)},key=p=>p.x+','+p.z,queue=[start],seen=new Map([[key(start),null]]);let found=null;
 for(let i=0;i<queue.length&&i<6000;i++){const p=queue[i];if(Math.hypot(p.x-goal.x,p.z-goal.z)<1.5){found=p;break;}for(const [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const q={x:p.x+dx,z:p.z+dz};if(seen.has(key(q))||!walkable(q.x*step,q.z*step))continue;seen.set(key(q),p);queue.push(q);}}
 if(!found)return null;const route=[];for(let p=found;seen.get(key(p));p=seen.get(key(p)))route.unshift(new THREE.Vector3(p.x*step,.45,p.z*step));if(clear(route.at(-1)||from,to))route.push(new THREE.Vector3(to.x,.45,to.z));return route.length?route:null;
}
function openDetail(){panelOpen=false;$('.panel').hidden=true;document.body.classList.toggle('menu-open',false);const d=$('#detailDialog');if(!d.open)d.show();}
function showCompactBuilding(kind,id){const h=kind==='home'?s.homes.find(h=>h.id===id):null,d=defs.find(d=>d.id===(h?'house':id));if(!d)return;const lv=h?h.level:level(s,id),cost=lv?upgradeCost(s,d,lv):d.cost,req=requirements(s,d),buttons=[];
 if(lv<d.forms.length)buttons.push({label:lv?'업그레이드':'위치 정하기',disabled:sea||!afford(cost)||(!lv&&req.length>0)||(lv&&!upgradeAllowed(d,lv)),action:()=>lv?upgrade(d.id,h?.id):build(d.id)});
 if(lv&&!['boat','ship'].includes(d.id))buttons.push({label:'이동',action:()=>startPlacement(d.id,'move',h?.id)});
 if(lv&&!['haven','fishing','boat','ship','house','cottages','council'].includes(d.id)&&!s.residents.some(r=>({wood:'lumber',stone:'quarry',food:'farm'})[r.jobKey]===d.id))buttons.push({label:'철거',action:()=>demolishBuilding(d)});
 if(lv)buttons.push({label:'찾기',action:()=>focusBuilding(h?.id||d.id)});
 if(d.id==='fishing')buttons.unshift({label:'낚시하러 가기',action:()=>chooseWorldAction({kind:'building',id:'fishing'},'fish')});
 lifeDialog(d.icon+' '+d.name+(lv?' · '+lv+'단계':''),'<p class="detail-cost">'+(lv>=d.forms.length?'최고 단계':fullCost(cost,true))+'</p>'+(req.length?'<p>거점 '+(GATES[d.id]||0)+'단계에서 열려요.</p>':'')+'<details><summary>자세히 보기</summary><p>'+d.desc+'</p><p>'+facilityEffect(d.id,Math.max(1,lv))+'</p></details>',buttons);
}
function demolishBuilding(d){if(!confirm(d.name+'을 철거할까요? 최초 건설 재료의 절반을 돌려받고 업그레이드는 사라져요.'))return;const returned=Object.fromEntries(Object.entries(d.cost).map(([k,n])=>[k,Math.floor(n/2)]));s.buildings[d.id]=0;delete s.placements[d.id];storeItems(s,returned);rebuild();save();render();toast(d.name+' 철거 · 재료 일부를 돌려받았어요.');}
function focusBuilding(id){const h=s.homes.find(h=>h.id===id),p=h||placementOf(id);focusPoint=new THREE.Vector3(p.x,0,p.z);zoom=18;}
